window.__CHRONICLE_CHUNK["wd-06"] = [
  {id:"world--1914--p01",track:"world",year:1914,yearApprox:false,dim:"politics",weight:5,title:"萨拉热窝事件",summary:"奥匈皇储夫妇在波斯尼亚首府遇刺，引爆欧洲外交危机。",detail:{background:"波斯尼亚1908年被奥匈吞并后，「青年波斯尼亚」等南斯拉夫民族主义组织与贝尔格莱德军方外围保持联系。",process:"1914年6月28日，皇储弗朗茨·费迪南与妻索菲在萨拉热窝检阅途中被青年普林西普开枪打死；奥方事先获知暗杀风险却未加强安保，总督波蒂奥雷克仍按原路线行车。",impact:"奥匈决策层视之为对塞尔维亚开战的契机，7月即启动限期通牒程序；同盟体系与总动员时间表使双边冲突在六周内扩为欧洲大战。",figures:["弗朗茨·费迪南","索菲·霍特克","加夫里洛·普林西普","奥斯卡·波蒂奥雷克"],place:"奥匈帝国波斯尼亚首府萨拉热窝（今波黑首都）",state:"奥匈帝国／塞尔维亚王国",sources:["奥地利菲施托夫国家档案馆藏奥匈帝国外交部档案（Haus-, Hof- und Staatsarchiv）","Luigi Albertini, The Origins of the War of 1914（英译本，1952—1957）"],tags:["刺杀","巴尔干","战争起源"]},related:[]},
  {id:"world--1914--p02",track:"world",year:1914,yearApprox:false,dim:"politics",weight:4,title:"七月危机与欧战爆发",summary:"奥塞通牒到期后列强依动员计划连锁宣战。",detail:{background:"德国在7月初向奥匈给出无条件支持的「空白支票」，奥方于7月23日向贝尔格莱德提出限期48小时答复的最后通牒。",process:"塞尔维亚7月25日接受大部分条款；7月28日奥匈对塞宣战并炮击贝尔格莱德；俄国先后宣布部分与总动员，德国8月1日对俄、3日对法宣战，4日因德军进入比利时而对英参战。",impact:"五周内欧陆主要国家全部卷入，同盟国与协约国阵营对峙成型；动员计划的刚性使外交斡旋（如英国最后照会）来不及生效。",figures:["贝特曼-霍尔维格","谢尔盖·萨宗诺夫","利奥波德·贝希托尔德","爱德华·格雷"],place:"维也纳、贝尔格莱德、圣彼得堡、柏林、巴黎、伦敦",state:"奥匈帝国／德国／俄国／法国／英国",sources:["《欧洲大战起源文件集》（各国外交档案汇编）","David Stevenson, Armaments and the Coming of War（1996）"],tags:["七月危机","宣战","同盟体系"]},related:[]},
  {id:"world--1914--m01",track:"world",year:1914,yearApprox:false,dim:"military",weight:5,title:"第一次马恩河战役",summary:"法英联军反击阻止德军逼近巴黎，速决计划破产。",detail:{background:"德军按修订后的施里芬计划经比利时南下，8月底在蒙斯、勒卡托、圣康坦连败法英军队，霞飞下令持续后撤。",process:"9月5日至12日，法军以新建第六军与英国远征军在马恩河一线反攻，德军第一、第二集团军之间出现数十公里缺口；克卢克与比洛先后下令后退，德军退守努瓦永至凡尔登一线转入筑垒对峙。",impact:"德国在西线速胜的可能丧失，战争转为长期消耗；此役奠定了霞飞的声望，也加深了法英对弹药与炮兵数量的急迫需求。",figures:["约瑟夫·霞飞","约翰·弗伦奇","亚历山大·冯·克卢克","卡尔·冯·比洛","费迪南·福煦"],place:"法国马恩河与乌鲁克河一带（巴黎东北）",state:"法国／英国／德意志帝国",sources:["法国官方战史《欧战中的法国军队》（1922—1938）","德国总参谋部官方战史《大战：1914—1918》"],tags:["马恩河","速决战","堑壕战"]},related:[]},
  {id:"world--1914--m02",track:"world",year:1914,yearApprox:false,dim:"military",weight:4,title:"坦能堡战役",summary:"德军合围歼灭俄国第二集团军，东普鲁士解围。",detail:{background:"俄军按法俄协定在动员未完时分两路侵入东普鲁士，萨宗诺夫与伦南坎普夫两军之间协同薄弱、无线电明码通信。",process:"8月26日至30日，第八集团军在兴登堡、鲁登道夫指挥下以部分兵力正面牵制、主力迂回侧后，在坦能堡与维伦堡地区完成合围；萨宗诺夫自尽，德方宣称俘获约9.2万人（俄方统计与实际损失存在出入，属估算）。",impact:"东普鲁士危机解除使兴登堡—鲁登道夫跃升为德国军政核心，深刻影响此后政治走向；德军为东线抽调兵力亦削弱了西线决胜窗口。",figures:["保罗·冯·兴登堡","埃里希·鲁登道夫","亚历山大·萨宗诺夫","普里特维茨"],place:"东普鲁士坦能堡、维伦堡（今波兰斯滕贝克、奥尔什丁）",state:"德意志帝国／俄国",sources:["埃里希·鲁登道夫《战争回忆录1914—1918》","德国总参谋部官方战史《大战：1914—1918》"],tags:["东线","合围","俄国"]},related:[]},
  {id:"world--1914--m03",track:"world",year:1914,yearApprox:false,dim:"military",weight:2,title:"西线圣诞自发停火",summary:"堑壕两侧士兵自发休战、互赠礼品并踢球。",detail:{background:"开战五个月后西线已成堑壕对峙，12月24日前后自伊普尔至阿尔芒蒂耶尔一带多段阵地出现无组织接触的停火。",process:"据多处部队战时日志、家书与战壕报刊记载，德英（含苏格兰部队）士兵走出堑壕，在无人地带互唱圣诞歌、交换香烟食品并踢足球；方面军司令随后明令禁止与敌接触，1915年起未再现规模性停火。",impact:"这一事件成为研究前线士兵态度与「敌我共情」界限的著名材料，战后被和平运动广泛引用，也说明士兵自发的秩序无法对抗总体战逻辑。",figures:["霍拉斯·史密斯-多林","约翰·弗伦奇"],place:"比利时伊普尔以南与法国北部堑壕地带",state:"英国／德意志帝国",sources:["英国帝国战争博物馆藏1914年部队战时日志与士兵家书","《每日电讯报》1914年12月31日刊载的前线来信"],tags:["堑壕战","士兵生活","停火"]},related:[]},
  {id:"world--1915--s01",track:"world",year:1915,yearApprox:false,dim:"science",weight:5,title:"爱因斯坦发表广义相对论场方程",summary:"引力场方程完成，引力被解释为时空几何。",detail:{background:"自1907年等效原理设想起，爱因斯坦与格罗斯曼引入黎曼度量描述引力，1913年的「纲要」理论因协变性不足受阻。",process:"1915年11月爱因斯坦在普鲁士科学院连续四次提交报告，11月25日给出以黎曼张量表达的引力场方程，并在同批报告中以新理论算出水星近日点进动值并修订光线偏折推定值。",impact:"广义相对论取代牛顿超距引力，成为宇宙学、引力波与致密天体研究的基础框架；与希尔伯特几乎同期获得方程一事学界长期并述。",figures:["阿尔伯特·爱因斯坦","大卫·希尔伯特","马塞尔·格罗斯曼"],place:"德国柏林（普鲁士科学院）",state:"德意志帝国",sources:["爱因斯坦《引力场方程》提交报告（1915年11月25日），见《爱因斯坦全集》第6卷","Abraham Pais, Subtle Is the Lord（1982）"],tags:["相对论","引力","物理学"]},related:[]},
  {id:"world--1915--p01",track:"world",year:1915,yearApprox:false,dim:"politics",weight:4,title:"奥斯曼帝国对亚美尼亚人的驱逐",summary:"知识分子被捕与迁徙法实施，沿途死亡惨重。",detail:{background:"1914年11月奥斯曼对俄英法开战；1915年4月凡城方向的冲突被用作清除亚美尼亚族群政治骨干的理由。",process:"4月24日君士坦丁堡逮捕数百名亚美尼亚知识分子与社区领袖；5月27日《迁徙法》通过，各省亚美尼亚人被强制迁徙进入叙利亚荒漠，途中因饥饿、袭击与处决大量死亡（死亡人数各估算自数十万至百万级，土耳其官方统计明显更低）。",impact:"学界多称此事件为亚美尼亚种族灭绝，土耳其官方则称之为战时迁徙与双方伤亡；该定性至今仍是土耳其对外关系与史学争论的议题。",figures:["塔拉特帕夏","恩维尔帕夏","亨利·摩根索"],place:"奥斯曼帝国东部六省与叙利亚荒漠迁徙路线",state:"奥斯曼帝国",sources:["美国驻奥斯曼大使亨利·摩根索的现场报告与信函（《摩根索大使故事》1918）","沃尔夫冈·居斯特编《德国与1915年亚美尼亚种族灭绝》（2005）"],tags:["种族灭绝","奥斯曼","战争暴力"]},related:[]},
  {id:"world--1915--m01",track:"world",year:1915,yearApprox:false,dim:"military",weight:4,title:"加里波利战役",summary:"协约国强渡达达尼尔失败，八个月后撤离滩头。",detail:{background:"为打通对俄海运、迫使奥斯曼退出战争，海军大臣丘吉尔主张以舰队强渡海峡；1915年2月19日至3月18日炮击损失数艘旧战列舰后改为登陆作战。",process:"4月25日在安扎克湾与海里斯角等滩头登陆，因兵力不足、地形破碎与土军坚决反击（第16师在凯马尔指挥下抢占高地）而停滞；12月至1916年1月分阶段秘密撤离，撤离反而最为成功。",impact:"协约国方面伤亡与病减员合计约数十万（土军伤亡各统计亦在二十万以上，均属估算）；此役成为土耳其民族叙事与澳新军团神话的共同起点。",figures:["伊恩·汉密尔顿","穆斯塔法·凯马尔","温斯顿·丘吉尔"],place:"奥斯曼帝国加里波利半岛（今土耳其恰纳卡莱）",state:"英国／法国／奥斯曼帝国",sources:["查尔斯·比恩《澳新军团在达达尼尔》（澳大利亚官方战史）","温斯顿·丘吉尔《世界危机》第一卷"],tags:["两栖登陆","达达尼尔","消耗"]},related:[]},
  {id:"world--1915--m02",track:"world",year:1915,yearApprox:false,dim:"military",weight:3,title:"第二次伊普尔与首次大规模毒气攻击",summary:"德军顺风释放氯气，撕开防线约六公里缺口。",detail:{background:"为牵制法军即将发动的香槟攻势，德军第四集团军在伊普尔突出部准备以氯气攻击，由哈贝尔团队负责技术实施。",process:"4月22日傍晚借风向释放氯气，法军第87师与第45（北非）师一线溃退，形成约六公里缺口；因德军预备队不足未能扩张战果，加拿大第一师等部以反冲击封闭部分缺口。",impact:"化学战自此成为常设手段，双方均大规模列装毒剂并互相升级；这一经验直接推动1925年《日内瓦议定书》禁止在战争中使用窒息性毒剂。",figures:["弗里茨·哈贝尔","埃德蒙·阿伦比","朱利安·比恩"],place:"比利时伊普尔突出部",state:"德意志帝国／法国／英国／加拿大",sources:["英国官方战史《欧战史：西线1915年》（詹姆斯·埃德蒙兹等）","《凡尔赛条约》第171条关于禁止毒气作战的条款"],tags:["化学战","伊普尔","武器变革"]},related:[]},
  {id:"world--1916--m01",track:"world",year:1916,yearApprox:false,dim:"military",weight:5,title:"凡尔登战役",summary:"德军以消耗战略进攻十月，双方损失极为惨重。",detail:{background:"法金汉主张选择凡尔登——突出部、仅靠一条公路补给、具象征意义的要塞群——以迫使法军「把血流尽」。",process:"2月21日大规模炮击后德军推进，2月25日夺杜奥蒙堡；贝当接手后以「圣路」轮运维持兵力与弹药，双方逐堡争夺；10月24日法军夺回杜奥蒙堡，12月中旬德军攻势终止。",impact:"法德两军皆受创极重（据法国与德国官方战史统计，双方伤亡合计约七十万至八十万，各口径差异大，属估算）；战役成为法国国家记忆的核心，也消耗了1916年协约国的进攻能力。",figures:["埃里希·冯·法金汉","菲利普·贝当","保罗·芒甘"],place:"法国默兹省凡尔登",state:"法国／德意志帝国",sources:["法国官方战史《欧战中的法国军队》","德国总参谋部官方战史《大战：1914—1918》"],tags:["消耗战略","要塞","凡尔登"]},related:[]},
  {id:"world--1916--m02",track:"world",year:1916,yearApprox:false,dim:"military",weight:4,title:"索姆河战役",summary:"英法联合进攻，英军首日伤亡惨重而推进有限。",detail:{background:"为减轻凡尔登压力并谋求突破，黑格准备以数天炮火准备后的正面进攻；战役于1916年7月1日发起。",process:"7月1日英军在北翼的进攻多被击退（英国官方战史记为单日伤亡约5.7万人，其中阵亡人数各记载在1.2万至1.9万之间），法军在南翼推进较多；9月15日弗莱尔-库尔塞莱特首次投入数十辆坦克；11月18日因秋冬天气停止行动。",impact:"暴露步兵正面突破筑垒地带的代价，推动坦克、步炮协同与弹性防御理论发展；英帝国志愿军在此役中完成向大军团的痛苦转化。",figures:["道格拉斯·黑格","亨利·罗林森","费迪南·福煦"],place:"法国索姆河流域（阿尔贝至马里卡）",state:"英国／法国／德意志帝国",sources:["英国官方战史《欧战史：军事行动 索姆河》（1927）","Gary Sheffield, Forgotten Victory（2001）"],tags:["索姆河","坦克","消耗战"]},related:[]},
  {id:"world--1916--m03",track:"world",year:1916,yearApprox:false,dim:"military",weight:4,title:"日德兰海战",summary:"英德主力舰队北海决战，英国保住战略制海权。",detail:{background:"舍尔计划以战列巡洋舰为饵诱出贝蒂分舰队，再由公海舰队主力与潜艇伏击将其分割歼灭。",process:"5月31日至6月1日，双方共二百余艘舰只在日德兰外海交战：英方损失3艘战列巡洋舰及多艘轻舰、阵亡约6900人，德方损失1艘旧战列舰、1艘战列巡洋舰与多艘轻舰、阵亡约3000人（数字据双方官方战史）。",impact:"战术交换比利于德国，但公海舰队此后不再寻求舰队决战，德国转向无限制潜艇战；英国海上封锁对德国经济与民生的压力因此持续。",figures:["约翰·杰利科","戴维·贝蒂","莱因哈德·舍尔","弗朗茨·冯·希佩尔"],place:"北海日德兰半岛以西洋面",state:"英国／德意志帝国",sources:["Arthur Marder, From the Dreadnought to Scapa Flow（1961—1970）","John Campbell, Jutland: An Analysis of the Fighting（1998）"],tags:["海战","制海权","战列舰"]},related:[]},
  {id:"world--1916--m04",track:"world",year:1916,yearApprox:false,dim:"military",weight:3,title:"布鲁西洛夫进攻",summary:"俄军宽正面多点突破，重创奥匈军队。",detail:{background:"为牵制奥军对意大利的制裁性攻势与德军在凡尔登的压力，西南方面军司令布鲁西洛夫主张在宽正面同时突击以分散敌预备队。",process:"5月22日起数个集团军在约三百公里正面同时突破，同盟国方面损失据双方档案估算约35万至40万人（其中被俘占半数以上），俄军自身损失亦达50万人以上（均为估算）；6月4日占领卢茨克，8月初克科韦尔，加利西亚重镇得手。",impact:"奥匈军队在指挥与后勤上进一步依附德军，罗马尼亚于8月27日对奥宣战参战；俄军巨大的消耗也削弱了其1917年的作战与士气基础。",figures:["阿列克谢·布鲁西洛夫","康拉德·冯·赫岑多夫"],place:"加利西亚与沃里尼亚（今乌克兰西部、波兰东南）",state:"俄国／奥匈帝国／德国",sources:["奥地利官方战史《奥匈帝国最后的战争》（1930年代）","Norman Stone, The Eastern Front 1875—1922（1975）"],tags:["东线","突破","奥匈"]},related:[]},
  {id:"world--1916--e01",track:"world",year:1916,yearApprox:false,dim:"economy",weight:3,title:"德国通过《辅助服务法》",summary:"强制适龄男子投入军工劳动，总体战经济成型。",detail:{background:"1916年8月兴登堡与鲁登道夫接管最高陆军指挥部后，由辛德斯与格勒纳主持国民经济的全面动员（兴登堡计划）。",process:"1916年12月2日《帮助战时服务法》经帝国议会通过：17至60岁男子战时可被强制安置于军工劳动，同时设立劳工介绍所并承诺在工厂设置工人代表机构，以换取社会民主党继续维持「和平团结」。",impact:"国家对社会劳动的强制调配被合法化，工会议价机制亦借此进入德国劳动法传统；该法与1918年11月革命及魏玛劳资协议制度存在直接延续关系。",figures:["埃里希·鲁登道夫","胡戈·辛德斯","瓦尔特·格勒纳"],place:"德国柏林",state:"德意志帝国",sources:["《帮助战时服务法》文本（1916年12月2日帝国议会通过，《帝国法律公报》1916年）","Roger Chickering, Imperial Germany and the Great War（2004）"],tags:["总体战","劳动管制","战时经济"]},related:[]},
  {id:"world--1917--p01",track:"world",year:1917,yearApprox:false,dim:"politics",weight:4,title:"俄国二月革命与沙皇退位",summary:"彼得格勒罢工演变为兵变，王朝终结。",detail:{background:"粮食供应紧张、前线伤亡与宫廷丑闻使统治集团失信，杜马中的自由派担忧沙皇单独媾和。",process:"3月8日起彼得格勒女工与工人罢工游行，3月12日卫戍部队士兵拒绝开枪并加入，杜马临时委员会组建李沃夫政府；3月15日尼古拉二世在普斯科夫签署退位书，出现临时政府与彼得格勒苏维埃并存的两权格局。",impact:"临时政府延续战争的政策使其持续失血，苏维埃凭《一号命令》掌握士兵组织；这一双重权力结构是同年10月事变的直接前提。",figures:["尼古拉二世","格奥尔基·李沃夫","帕维尔·米留可夫","尼古拉·齐赫泽"],place:"俄国彼得格勒、普斯科夫",state:"俄国",sources:["《1917年2至10月俄国革命法令与文件汇编》","Rex Wade, The Russian Revolution, 1917（2005）"],tags:["革命","退位","双重政权"]},related:["world--1917--p02"]},
  {id:"world--1917--p02",track:"world",year:1917,yearApprox:false,dim:"politics",weight:5,title:"十月革命与苏维埃政权建立",summary:"布尔什维克以武力接管彼得格勒，组建人民委员会。",detail:{background:"七月危机与科尔尼洛夫事件后，布尔什维克在莫斯科与彼得格勒苏维埃占多数，中央委员会10月10日、16日通过武装起义方针。",process:"11月7日革命军事委员会控制电话局、车站与桥梁，冬宫在次日凌晨被攻占；第二届全俄苏维埃代表大会通过《和平法令》与《土地法令》，选出以列宁为主席的人民委员会。",impact:"新政权以一党权力与「和平、土地、面包」纲领夺国，随即以布列斯特和约退出战争；苏维埃国家的出现把社会主义与民族自决问题推入20世纪国际秩序。",figures:["列宁","托洛茨基","斯大林","阿道夫·越飞"],place:"俄国彼得格勒（冬宫、斯莫尔尼宫）",state:"俄国",sources:["第二届全俄苏维埃代表大会会议记录与《和平法令》《土地法令》文本","Orlando Figes, A People's Tragedy（1996）"],tags:["布尔什维克","夺权","苏维埃"]},related:["world--1918--p01"]},
  {id:"world--1917--p03",track:"world",year:1917,yearApprox:false,dim:"politics",weight:4,title:"美国对德宣战",summary:"潜艇战与齐默尔曼电报把美国推入战争。",detail:{background:"德国2月1日宣布恢复无限制潜艇战，2月3日美国与德绝交；2月24日公布的齐默尔曼电报（德提议与墨同盟对美作战）扭转舆论。",process:"4月2日威尔逊以「世界应为民主安全」为题咨请国会，4月6日参众两院通过对德宣战、12月7日对奥宣战；5月18日《选征兵役法》通过后共征召约280万人，赴欧约200万。",impact:"美国的财政、工业与兵源介入使协约国的消耗战潜力发生决定性倾斜；威尔逊对战争目的的表述成为战后秩序设计的纲领导向。",figures:["伍德罗·威尔逊","阿瑟·齐默尔曼","埃农·伍德"],place:"美国华盛顿／德国柏林",state:"美国／德意志帝国",sources:["威尔逊1917年4月2日国会两院联席会议演说文本","David Kennedy, Over Here: The First World War and American Society（1999）"],tags:["美国参战","潜艇战","战争目的"]},related:["world--1917--m01"]},
  {id:"world--1917--p04",track:"world",year:1917,yearApprox:false,dim:"politics",weight:3,title:"贝尔福宣言",summary:"英政府表态赞成在巴勒斯坦建立犹太民族家园。",detail:{background:"英国战时内阁就犹太人问题与中东安排辩论经年，魏茨曼等犹太复国主义者争取以外交承认为战争之外的目标。",process:"11月2日外交大臣贝尔福致函罗斯柴尔德勋爵，声明政府「赞成在巴勒斯坦为犹太民族建立一个民族家园」，并载明不得损害当地既非犹太各民族的公民与宗教权利；11月9日见报公布。",impact:"该函后被1920年圣雷莫巴勒斯坦委任统治条款引用，成为阿犹冲突叙事的原始文本之一；其措辞的解释空间延续到历次白皮书与1947年分治决议。",figures:["阿瑟·贝尔福","哈伊姆·魏茨曼","马克·赛克斯"],place:"英国伦敦",state:"英国",sources:["《贝尔福致罗斯柴尔德勋爵函》（1917年11月2日）正文","Roger Louis, The British Empire in the Middle East 1914—1951（1969）"],tags:["委任统治","犹太复国主义","中东"]},related:[]},
  {id:"world--1917--m01",track:"world",year:1917,yearApprox:false,dim:"military",weight:4,title:"德国恢复无限制潜艇战",summary:"潜艇不加警告攻击一切商船，护航制随后重建。",detail:{background:"兴登堡与鲁登道夫判断可在美国运力成型前迫使英国求和，1917年1月9日的德国内阁与军政会议作出决定。",process:"2月1日德国宣布自2月1日起在不列颠周边、法国与意大利海域及地中海不加警告击沉一切船只；头数月盟国商船月均损失逾50万总吨，4月起试行护航、7月起跨洋护航编队常态化，11月损失降至约29万总吨（据英国海军部战时统计，属估算）。",impact:"这一决策在军事上未能扼断英国海运，政治上却促成美国参战；护航编队、声呐与远程巡逻等反潜体系的制度化由此开始。",figures:["亨宁·冯·霍尔岑多夫","约翰·杰利科","卡尔·邓尼茨"],place:"北海、大西洋东部与比斯开湾",state:"德意志帝国／英国",sources:["英国官方战史《海军作战史》（朱利安·科贝特等，1938）","卡尔·邓尼茨《十年与二十天》（1958）"],tags:["潜艇战","护航","海运战"]},related:["world--1917--p03"]},
  {id:"world--1917--d01",track:"world",year:1917,yearApprox:false,dim:"disaster",weight:2,title:"哈利法克斯大爆炸",summary:"军火船在新斯科舍港内爆炸，约两千人死难。",detail:{background:"哈利法克斯是协约国向欧洲运兵运货的冬季集结港，港内常年停泊载炸药与易燃品的船只。",process:"12月6日晨，载有约2300吨炸药与易燃品的法国船蒙特-布兰克号与挪威船伊莫号相撞起火，约20分钟后爆炸，冲击波与随后涌入的海水摧毁河岸街区；死亡约1900至2000人、伤者逾万（据1918年凯洛格法官调查记录）。",impact:"爆炸推动了港口危险品管制与消防、伤科救治的标准化；枢密院司法委员会1919年就该爆炸火灾损害的裁定，成为侵权法讨论因果与损害远隔性的经典判例。",figures:["欧文·凯洛格"],place:"加拿大新斯科舍省哈利法克斯港",state:"加拿大／英国",sources:["1918年凯洛格法官就碰撞与爆炸所提调查记录（加拿大议会文件）","枢密院司法委员会《加拿大太平洋铁路公司诉罗伊案》裁定（1919年）"],tags:["爆炸","港口","城市灾害"]},related:[]},
  {id:"world--1918--p01",track:"world",year:1918,yearApprox:false,dim:"politics",weight:4,title:"布列斯特-利托夫斯克和约",summary:"苏俄退出战争，放弃波兰、乌克兰与波罗的海。",detail:{background:"人民委员会以求和立国，12月起在布列斯特谈判；1918年2月德方提出更苛刻条件后，托洛茨基宣布「既不签约也不作战」。",process:"2月18日德军全面推进，3月3日苏俄签约：承认乌克兰独立、放弃波罗的海与波兰、割让卡尔斯等地并支付60亿马克；同年11月德国战败后，苏俄政府宣布该约废止。",impact:"和约给新政权换来喘息，却付出巨大领土与资源代价（据苏方统计，失去前帝国欧洲部分约三分之一人口与约四分之三煤铁产能，属估算），也激化了与左派社会革命党人的冲突。",figures:["列宁","托洛茨基","布哈林","阿道夫·越飞"],place:"布列斯特-利托夫斯克（今白俄罗斯布列斯特）",state:"苏维埃俄国／德意志帝国",sources:["《布列斯特-利托夫斯克和约》正文与批准书（1918年3月）","《苏维埃俄国外交人民委员部文件汇编》"],tags:["退出战争","割地","苏德关系"]},related:["world--1917--p02"]},
  {id:"world--1918--m01",track:"world",year:1918,yearApprox:false,dim:"military",weight:4,title:"德军春季攻势",summary:"三次突击皆以耗尽预备队告终，主动权易手。",detail:{background:"东线兵力西调使德军在西线取得数量优势，鲁登道夫想在美军成型前于佛兰德与瓦兹河一线打开缺口。",process:"3月21日「米夏埃尔」行动在索姆河突破并推进约60公里，4月9日至12日佛兰德「乔尔赫」行动、5月27日「布吕歇尔-约克」行动直逼马恩河；协约国4月14日设福煦协调委员会、6月3日任总司令，德军因补给与兵力枯竭停止扩张。",impact:"攻势耗掉德军最精锐的突击兵力，7月18日协约国在马恩河反攻、8月8日亚眠之战后鲁登道夫承认「德国精神的末日」，德军由攻转守。",figures:["埃里希·鲁登道夫","费迪南·福煦","道格拉斯·黑格","威廉·格勒纳"],place:"法国北部索姆河、利斯河与瓦兹河地带",state:"德意志帝国／法国／英国",sources:["德国总参谋部官方战史《大战：1914—1918》","英国官方战史《欧战史：1918年英国军队在法国》"],tags:["春季攻势","突破","消耗战"]},related:["world--1918--p03"]},
  {id:"world--1918--p02",track:"world",year:1918,yearApprox:false,dim:"politics",weight:4,title:"德国革命与共和国宣布",summary:"基尔水兵起义迫使皇室退位，魏玛共和成立。",detail:{background:"10月3日巴登亲王政府奉命寻求停战，海军司令部10月底命令公海舰队出击，官兵拒绝作「和平条件的牺牲品」。",process:"10月29日至11月3日基尔水兵拒绝出港并选出工兵代表苏维埃，起义蔓延至汉堡、慕尼黑；11月9日柏林总罢工与示威，巴登亲王宣布威廉二世退位并移交总理职务，谢德曼宣布共和国，李卜克内西另呼社会主义共和国。",impact:"帝制终结而军队建制与社会结构未被动摇，「背后中刀」传说自此侵蚀共和合法性；12月斯巴达克同盟建党，1919年1月柏林起义遭血腥镇压。",figures:["弗里德里希·艾伯特","菲利普·谢德曼","卡尔·李卜克内西","马克斯·冯·巴登"],place:"德国基尔、柏林",state:"德意志帝国／德意志共和国",sources:["艾伯特与格勒纳1918年11月10日通话记录（见《共和国的诞生》文件集）","埃里希·马蒂亚斯《德国革命1918—1919》（1968）"],tags:["十一月革命","退位","共和"]},related:["world--1919--i01"]},
  {id:"world--1918--p03",track:"world",year:1918,yearApprox:false,dim:"politics",weight:5,title:"康边停战协定",summary:"11月11日11时生效，西线战事终止。",detail:{background:"9月29日兴登堡与鲁登道夫承认态势不可恃，10月3日新政府照会威尔逊，但军方又拖延以图再战。",process:"11月6日埃尔茨贝格率团赴康边森林，福煦委派魏冈在车厢内签署，凌晨5时（德方时间）成文、11时生效：德军退至莱茵河左岸并在右岸保留三个桥头堡，交出潜艇与主力舰、销毁重炮，封锁继续维持，东线德军原地停留。",impact:"「未战败而停战」的印象成为凡尔赛「强加和平」论调的温床；停战划出的权力真空使中欧在1918至1921年间连续发生边界战争。",figures:["费迪南·福煦","马蒂亚斯·埃尔茨贝格","马克西姆·魏冈"],place:"法国康边（贡比涅）森林",state:"法国／英国／德意志共和国",sources:["《1918年11月11日停战协定》正文（法国与英国官方文本）","John Keegan, The First World War（1998）"],tags:["停战","莱茵撤退","战后起点"]},related:["world--1919--p01"]},
  {id:"world--1918--p04",track:"world",year:1918,yearApprox:false,dim:"politics",weight:3,title:"奥匈帝国解体",summary:"继承国家相继宣布独立，君主国终结。",detail:{background:"威尔逊以民族自决为停战前提，帝国各族国民委员会自9月起已宣布组建意图；10月24日意大利发动维托里奥·威内托攻势。",process:"10月28日布拉格宣布捷克斯洛伐克共和国，10月29日萨格勒布宣布塞尔维亚人-克罗地亚人-斯洛文尼亚人国，11月1日波兰人接管克拉科夫；11月3日朱斯蒂停战，11月11日卡尔皇帝声明不参与国事。",impact:"中欧统一的关税与行政空间裂为若干新国家，德意志少数与越境族群问题（苏台德、南蒂罗尔、伏伊伏丁那）成为两次大战之间直至1990年代冲突的根源。",figures:["卡尔一世","托马斯·马萨里克","安东·科罗舍茨"],place:"维也纳、布拉格、萨格勒布、卢布尔雅那",state:"奥匈帝国／捷克斯洛伐克／塞尔维亚人-克罗地亚人-斯洛文尼亚人国",sources:["奥地利官方战史《奥匈帝国最后的战争》","A. J. P. Taylor, The Habsburg Monarchy 1815—1918（修订版1948）"],tags:["帝国解体","民族自决","中欧"]},related:["world--1918--p05"]},
  {id:"world--1918--p05",track:"world",year:1918,yearApprox:false,dim:"politics",weight:3,title:"波兰恢复独立",summary:"摄政委员会宣告主权，毕苏斯基接管军政。",detail:{background:"1916年11月德奥曾公告「波兰王国」以募集兵源；1918年1月威尔逊十三点明确提出独立波兰与出海口。",process:"10月7日华沙摄政委员会宣布独立，10月28日克拉科夫的波兰人国民委员会接管加里西亚；11月10日毕苏斯基抵华沙，11月11日接掌军事权，11月14日临时政府成立并获协约国承认。",impact:"复国把波兰问题转为现实的边界与少数族群问题（但泽、西里西亚、东加利西亚），1919至1921年连续与德、苏、立陶宛和乌克兰发生边界战争，塑造了凡尔赛体系的东翼。",figures:["约瑟夫·毕苏斯基","罗曼·德莫夫斯基"],place:"华沙、克拉科夫、波兹南",state:"波兰",sources:["1918年10月7日华沙摄政委员会独立公告","《凡尔赛条约》第87至95条关于波兰边界的规定"],tags:["复国","边界","东欧"]},related:["world--1920--m01"]},
  {id:"world--1918--d01",track:"world",year:1918,yearApprox:false,dim:"disaster",weight:5,title:"西班牙流感全球大流行",summary:"三波疫情在十八个月内造成数千万人死亡。",detail:{background:"病毒沿战时军营与运输线放大传播；中立国西班牙的战时新闻审查较宽，疫情首见其报端而得名。",process:"1918年3月美国芬斯顿营与法英训练营地出现第一波，6至11月第二波致死率骤升，1919年冬与1920年春另有两波；据约翰森与穆勒2002年重新核算，全球死亡约5,000万至1亿人，其中印度约1,200万至1,800万（属统计估算）。",impact:"疫情在一年半内逆转多国的死亡与出生结构、留下劳动力缺口，并暴露公共卫生体系的战时脆弱；它成为20世纪流行病学、疫苗学与疫情通报制度的分水岭。",figures:["西蒙·弗克斯内尔"],place:"全球（首发地存在美国、法国与英军营地诸说）",state:"国际",sources:["Niall Johnson & Juergen Mueller, Bulletin of the History of Medicine 76（2002）","John M. Barry, The Great Influenza（2004）"],tags:["瘟疫","大流行","人口损失"]},related:["world--1918--p03"]},
  {id:"world--1919--p01",track:"world",year:1919,yearApprox:false,dim:"politics",weight:5,title:"《凡尔赛条约》签订",summary:"和约重划德国疆界并规定战争责任与赔款。",detail:{background:"1月18日巴黎和会开幕，实际决策由美英法政府首脑及其顾问的「四人会议」主导，德方未参与谈判而只获提交文本。",process:"6月28日在凡尔赛宫镜厅签署：德国接受第231条战争责任条款，归还阿尔萨斯-洛林，承认波兰与捷克斯洛伐克，但泽置于国际保护，莱茵左岸非军事化，陆军限10万人，殖民地以委任统治分配。",impact:"条约未能把德国纳入平等的安全安排，责任条款与赔款成为民族主义动员的核心靶点；美国参议院1919年11月与1920年3月两度否决，对德和约由1921年单独和约补足。",figures:["伍德罗·威尔逊","乔治·克列孟梭","劳合-乔治","赫尔曼·米勒"],place:"法国凡尔赛宫镜厅",state:"德国／协约国与关联国家",sources:["《凡尔赛条约》正文（1919年6月28日，法国官方文本）","Margaret MacMillan, Peacemakers（2001）"],tags:["和约","战争责任","委任统治"]},related:["world--1919--i01"]},
  {id:"world--1919--i01",track:"world",year:1919,yearApprox:false,dim:"institution",weight:4,title:"魏玛宪法生效",summary:"比例代表制共和宪制确立，第48条留有紧急权。",detail:{background:"1919年2月6日按普遍与比例选举选出国民议会，因柏林局势开会于魏玛；起草由内务部国家秘书普鲁斯主持。",process:"7月31日议会以262票对75票通过宪法，8月11日公布生效：主权属于人民，总统由直选产生、任期七年，可依据第48条以紧急命令「恢复公共安全与秩序」，基本权利列为纲领性章节。",impact:"这是当时欧洲最民主的宪制文本，却同时设置直选总统与议会两极，比例制又降低小党门槛；紧急命令与「双重合法性」在1930至1933年的运用成为共和解体的制度通道。",figures:["胡戈·普鲁斯","弗里德里希·艾伯特","马克斯·韦伯"],place:"德国魏玛、柏林",state:"德意志共和国",sources:["《魏玛宪法》正文（1919年8月《帝国法律公报》）","Hagen Schulze, Weimar: Deutschland 1917—1933（1982）"],tags:["宪法","比例代表","紧急命令"]},related:[]},
  {id:"world--1919--s01",track:"world",year:1919,yearApprox:false,dim:"science",weight:4,title:"日食观测证实光线偏折",summary:"两支远征队测得星光偏折值与广义相对论相符。",detail:{background:"爱因斯坦1911年的偏折推算值仅为后来的半量，1915年场方程给出约1.75角秒；5月29日的日全食是当时的检验窗口。",process:"爱丁顿率队赴巴西索布拉尔、克罗姆林率队赴西非普林西比岛拍摄日冕中恒星位置；11月6日皇家学会与皇家天文学会联合会议宣布偏折测量值与广义相对论预言一致（两站结果的误差处理在科学史上长期被讨论）。",impact:"这次观测让相对论同时在学界与公众中确立声誉，形成以天文检验判定时空理论的方法范例，也充当了战后英国与德国科学关系重建的契机。",figures:["亚瑟·爱丁顿","弗兰克·沃森-戴维","安德鲁·克罗姆林"],place:"巴西索布拉尔、普林西比岛、英国伦敦",state:"英国",sources:["《皇家学会日食委员会备忘录》第2号（1920）","Arthur Eddington, Space, Time and Gravitation（1920）"],tags:["相对论","天文观测","科学验证"]},related:["world--1915--s01"]},
  {id:"world--1919--a01",track:"world",year:1919,yearApprox:false,dim:"art",weight:3,title:"国立包豪斯在魏玛成立",summary:"格罗皮乌斯合并工艺与美术学校，重提建筑总体性。",detail:{background:"魏玛的撒克逊工艺学校与美术学院因革命与预算改组，年方三十六岁的格罗皮乌斯被任命为新校校长。",process:"1919年4月两校合并为「国立包豪斯」，同年以费宁格木刻大教堂为封面的《包豪斯宣言》刊出，主张建筑、雕塑与绘画回归工艺；课程设材料与色彩的基础训练，1922年起延请康定斯基、克利、莫霍利-纳吉执教。",impact:"包豪斯把设计教育制度化，形成以材料、功能与批量生产为轴的现代设计语言；1925年迁德绍、1932年迁柏林、1933年被关闭后，师生流散把该体系输出至美国、巴勒斯坦与英国。",figures:["瓦尔特·格罗皮乌斯","费宁格","康定斯基","保罗·克利"],place:"德国魏玛",state:"德意志共和国",sources:["《包豪斯宣言》（1919年，格罗皮乌斯执笔）","Hans Wingler, The Bauhaus: Weimar, Dessau, Berlin 1919—1933（英译本1969）"],tags:["设计教育","现代主义","建筑"]},related:["world--1919--i01"]},
  {id:"world--1919--p02",track:"world",year:1919,yearApprox:false,dim:"politics",weight:3,title:"阿姆利则事件",summary:"英军向围合场地内的集会持续射击十分钟。",detail:{background:"《罗拉特法》允许不经审判拘禁。4月10日萨特亚帕尔与基奇卢两位医生被捕，旁遮普多地骚动；戴尔抵达阿姆利则后禁止公开集会。",process:"4月13日傍晚，朱利安瓦勒巴格场内正举行集会与比斯赫节聚会，戴尔率廓尔喀与锡克士兵封锁出口、以机枪持续射击约十分钟；英方统计死379人、伤约1200人，国大党自行调查记为逾千（两组数字并存）。",impact:"事件摧毁了甘地对帝国公正的期待，推动同年秋天的不合作纲领；亨特委员会内部分歧与下院多数票谴责，成为殖民暴力问责的标志性案例。",figures:["雷金纳德·戴尔","米格尔·亨特","圣雄甘地"],place:"英属印度旁遮普省阿姆利则",state:"英属印度",sources:["《旁遮普骚乱调查委员会报告》（亨特委员会，1920年）","印度国大党调查委员会《旁遮普暴行》（1920年）"],tags:["殖民暴力","集会","问责"]},related:["world--1920--p02"]},
  {id:"world--1920--p01",track:"world",year:1920,yearApprox:false,dim:"politics",weight:5,title:"国际联盟正式成立",summary:"盟约随和约生效，日内瓦成为集体安全机制总部。",detail:{background:"《凡尔赛条约》第一编即《国际联盟盟约》，威尔逊把它作为十四点的制度枢纽，但美国参议院最终否决加入。",process:"1920年1月10日和约生效、国联正式成立，11月15日首届大会在日内瓦召开；行政院由英法意日常任加六非常任构成，设秘书长（首任德拉蒙德）、国际劳工组织与常设国际法院并行运作。",impact:"国联把委任统治、少数族群保护与裁军谈判纳入常设多边程序，其决议虽缺强制力，却奠定了此后国际组织的技术官僚模式；缺席美国与苏俄使其在1930年代危机中先天不足。",figures:["埃里克·德拉蒙德","莱昂·布尔热瓦","伍德罗·威尔逊"],place:"法国巴黎／瑞士日内瓦",state:"国际联盟",sources:["《国际联盟盟约》正文（1919年，随《凡尔赛条约》生效）","E. N. Walters, A History of the League of Nations（1952）"],tags:["集体安全","委任统治","多边机制"]},related:["world--1919--p01"]},
  {id:"world--1920--m01",track:"world",year:1920,yearApprox:false,dim:"military",weight:4,title:"华沙战役",summary:"毕苏斯基由侧翼反攻，红军在维斯拉河溃退。",detail:{background:"1920年春季图哈切夫斯基部向基辅与明斯克推进，7月在明斯克胜利后下令「跨过尸体走向华沙与列宁格勒」。",process:"8月上旬波军在华沙外围与新格鲁多克方向苦战，毕苏斯基坚持以维普日河以南的波军突击红军左翼的方案；8月16日至25日红军全线溃退，据戴维斯统计，红军阵亡、失踪与被俘合计约6.5万至7万人（属估算）。",impact:"此役保住了刚复国的波兰，1921年里加和约划定东界；红军受创促使军事思想转向纵深作战理论，也加深了苏波两国之间长达二十年的敌意。",figures:["约瑟夫·毕苏斯基","米哈伊尔·图哈切夫斯基","西科斯基"],place:"波兰华沙与维普日河、维斯拉河地带",state:"波兰／苏维埃俄国",sources:["Norman Davies, White Eagle, Red Star: The Polish-Soviet War 1919—1920（1972）","Adam Zamoyski, The Polish Way（1987）"],tags:["华沙","苏波战争","反攻"]},related:["world--1921--p01"]},
  {id:"world--1920--p02",track:"world",year:1920,yearApprox:false,dim:"politics",weight:3,title:"甘地发起不合作运动",summary:"放弃头衔、抵制法庭学校与英货，第一次全印群众运动。",detail:{background:"罗拉特法与阿姆利则事件使甘地放弃对帝国公正的期待，基拉法运动则提供了印度教徒与穆斯林联合的契机。",process:"1920年9月加尔各答全印国大党特别会议通过不合作纲领，12月那格浦尔年会予以确认：放弃英国授勋、抵制法庭与官立学校、抵制英货并推广土布；1921年至1922年初罢课、罢市与和平游行遍及数省。",impact:"运动把国大党组织从精英讨论团体变为覆盖县乡的群众机器；1922年2月乔里乔拉事件后甘地单方面终止运动，确立以「非暴力」为前提的动员纪律标准。",figures:["圣雄甘地","莫提拉尔·尼赫鲁","邵卡特·阿里"],place:"英属印度（加尔各答、那格浦尔、联合省）",state:"英属印度",sources:["《甘地全集》（一百卷本）所载1920年宣言与书信","Judith M. Brown, Gandhi: Prisoner of Hope（1989）"],tags:["非暴力","民族主义","抵制"]},related:["world--1930--p01"]},
  {id:"world--1920--p03",track:"world",year:1920,yearApprox:false,dim:"politics",weight:3,title:"《色佛尔条约》签订",summary:"素丹政府接受瓜分方案，安卡拉议会拒绝批准。",detail:{background:"协约国在圣雷莫（1920年4月）已分配近东委任统治地，素丹政府在协约国占领下的伊斯坦布尔被迫签约。",process:"8月10日在巴黎近郊塞夫尔签订：东色雷斯与伊兹密尔腹地归希腊、叙利亚与黎巴嫩归法国委任、美索不达米亚与巴勒斯坦归英国、海峡由国际委员会共管、亚美尼亚与库尔德地区交由仲裁与自治，并规定奥斯曼财政与军备受管制。",impact:"大国民议会宣布条约无效，安卡拉军队在两线作战后以《洛桑条约》取代之；该约的失败成为土耳其民族主义史学论证「革命建国」合法性的起点。",figures:["穆罕默德六世","乔治·寇松","穆斯塔法·凯马尔"],place:"法国塞夫尔（巴黎近郊）",state:"奥斯曼帝国／协约国",sources:["《色佛尔条约》正文（1920年8月10日）","Feroz Ahmad, The Making of Modern Turkey（1993）"],tags:["瓜分","委任统治","土耳其"]},related:["world--1923--p01"]},
  {id:"world--1921--e01",track:"world",year:1921,yearApprox:false,dim:"economy",weight:4,title:"苏俄推行新经济政策",summary:"以粮食税代替余粮收集制，容许小商品与私人贸易。",detail:{background:"战时共产主义的强制征粮引发农民普遍抗税与饥荒，1921年春全国暴动频起，喀琅施塔得兵变敲响警钟。",process:"俄共（布）第十次代表大会3月15日通过《关于以实物税代替余粮收集制》决议，税后可自由处置余粮；随后允许小工业私营、实行租让制并于1921年10月设立国家银行推进货币改革。",impact:"新经济政策在数年内恢复了农业与消费品生产，却也造成「耐普曼」阶层、失业与粮价波动的争论；1928至1929年被斯大林以非常措施终结，转向指令性计划经济。",figures:["列宁","布哈林","索科尔尼科夫"],place:"苏俄莫斯科",state:"苏维埃俄国",sources:["俄共（布）十大《关于以实物税代替余粮收集制》决议文本","E. H. Carr, The Bolshevik Revolution 1917—1923（1950）"],tags:["新经济政策","粮食税","退却"]},related:["world--1921--p01"]},
  {id:"world--1921--p01",track:"world",year:1921,yearApprox:false,dim:"politics",weight:3,title:"喀琅施塔得水兵起义",summary:"要塞以「要苏维埃、不要布尔什维克」口号被强攻镇压。",detail:{background:"水兵不满征粮、一党专政与配给制度，1921年2月彼得格勒同时发生工人罢工。",process:"2月底「彼得罗巴甫洛夫斯克」号通过决议要求改选苏维埃与释放政治犯；3月2日起义者在要塞布防，3月17日至18日夜间图哈切夫斯基率部踏冰强攻，攻陷要塞后有数百人被处决（具体数字各说不一，属估算）。",impact:"起义迫使领导层同时作出经济退却（新经济政策）与政治收紧（十大通过禁止派别活动的《关于党的统一》决议），后一决议成为此后党内清洗的程序依据。",figures:["列宁","图哈切夫斯基","卡尔·拉狄克"],place:"苏俄喀琅施塔得（芬兰湾科特林岛）",state:"苏维埃俄国",sources:["俄共（布）十大决议与《真理报》1921年3月报道","E. H. Carr, The Bolshevik Revolution 1917—1923（1950）"],tags:["兵变","党内统一","镇压"]},related:["world--1921--e01"]},
  {id:"world--1921--p02",track:"world",year:1921,yearApprox:false,dim:"politics",weight:3,title:"华盛顿会议召开",summary:"十五国集会讨论太平洋与军备限制问题。",detail:{background:"美日在太平洋与西伯利亚的扩张冲突、海军军备竞赛与英日同盟到期，使哈丁政府主张以多边会议替代双边安排。",process:"11月12日会议在华盛顿开幕，美、英、日、法、意、比、荷、葡与中国北洋政府九方参加，分设海军限制与远东太平洋两个委员会；中国北洋政府代表团提出恢复领土与关税主权要求。",impact:"会议以条约形式终止英日同盟并把西太平洋力量对比写入比例表，构成凡尔赛体系在亚洲的延伸；中国的诉求大多落空，门户开放原则被重新确认。",figures:["查尔斯·埃文斯·休斯","加藤友三郎","贝尔福"],place:"美国华盛顿",state:"美国／英国／日本／法国／意大利",sources:["《美国外交关系：华盛顿会议文件》（美国国务院，1922）","Akira Iriye, After Imperialism: The Search for a New Order in the Far East, 1921—1931（1965）"],tags:["军备限制","太平洋秩序","多边会议"]},related:["world--1922--p01", "cn--1922--p01"]},
  {id:"world--1921--s01",track:"world",year:1921,yearApprox:false,dim:"science",weight:4,title:"胰岛素首次用于人体",summary:"多伦多实验室的胰腺提取物首次注射糖尿病患者。",detail:{background:"1921年夏班廷在麦克劳德提供的实验室条件下结扎犬胆管以取得抗糖尿病提取物，与研究生贝斯特一同制备。",process:"10月31日，十四岁患者伦纳德·汤普森接受提取物注射，血糖与尿糖下降；因提纯不足而反应不佳，1921年末至1922年初科利普加入完成纯化工艺，1922年1月起用于多名患者，1923年获诺贝尔生理学或医学奖。",impact:"胰岛素把一型糖尿病从致死症转为可控病，确立「激素替代疗法」范式，也开创大学实验室与制药企业（礼来）合作的量产模式，引发长期的专利与优先权争议。",figures:["弗雷德里克·班廷","查尔斯·贝斯特","约翰·麦克劳德","詹姆斯·科利普"],place:"加拿大多伦多大学",state:"加拿大",sources:["多伦多大学班廷档案藏实验记录（1921年10至12月）","Michael Bliss, The Discovery of Insulin（1982）"],tags:["医学","激素","糖尿病"]},related:["world--1928--s01"]},
  {id:"world--1922--p01",track:"world",year:1922,yearApprox:false,dim:"politics",weight:4,title:"华盛顿三条约签署",summary:"四国、五国与九国条约同时签字，重排太平洋秩序。",detail:{background:"海军委员会由美英日法意五国谈判主力舰限额，远东问题另组委员会并单独处理山东与租界议题。",process:"2月6日签署三份条约：《四国条约》使英日同盟终止并约定太平洋岛屿现状；《五国海军条约》定主力舰吨位比例五比五比三比一点七五比一点七五并冻结要塞建设；《九国公约》重申中国主权、领土完整与门户开放。",impact:"华盛顿体系以条约网络冻结了军备与扩张，暂时缓解了美日矛盾；日本的相对受限与中国的半开放状态成为1931至1937年两国突破现状的直接口实。",figures:["查尔斯·埃文斯·休斯","加藤友三郎","贝尔福"],place:"美国华盛顿",state:"美国／英国／日本／法国／意大利",sources:["《四国条约》《五国海军条约》《九国公约》正文（美国国务院刊本，1922）","Akira Iriye, After Imperialism（1965）"],tags:["海军比例","门户开放","条约体系"]},related:["world--1921--p02"]},
  {id:"world--1922--p02",track:"world",year:1922,yearApprox:false,dim:"politics",weight:5,title:"法西斯进军罗马",summary:"国王拒绝戒严，授权墨索里尼组阁。",detail:{background:"1921至1922年法西斯武装队（黑衫军）在波河流域与南欧以暴力摧毁工会与合作社，自由派政府依赖其「制衡左翼」功能。",process:"10月27日至29日黑衫军在拉齐奥与翁布里亚数点集结并向罗马推进（集结人数各记为三至四万）；10月28日晚内阁建议戒严，国王维托里奥·埃马努埃莱三世拒绝并于29日授权墨索里尼组阁，10月31日新政府就职。",impact:"以合宪程序完成的法西斯独裁开端成为20世纪反议会运动的样板；1924年马泰奥蒂遇害与1925至1926年法令最终取消选举竞争与结社自由。",figures:["贝尼托·墨索里尼","维托里奥·埃马努埃莱三世","埃米利奥·德·博诺"],place:"意大利罗马与拉齐奥、翁布里亚集结地",state:"意大利王国",sources:["1922年10月29日授命组阁的官方公报与国王侍从官日记","Renzo De Felice, Mussolini: A Short Life（1982）"],tags:["法西斯","组阁","反议会"]},related:["world--1922--p03"]},
  {id:"world--1922--p03",track:"world",year:1922,yearApprox:false,dim:"politics",weight:5,title:"苏维埃社会主义共和国联盟成立",summary:"四国以条约结成联盟，1924年宪法确立建制。",detail:{background:"内战结束后，联共（布）中央在「自治化」与「联盟」两案间选择后者，列宁批评大国沙文主义倾向。",process:"12月30日第一次全苏维埃代表大会通过《苏联成立宣言》与《联盟条约》，俄罗斯、乌克兰、白俄罗斯与外高加索联邦四个加盟共和国联合；1924年1月宪法规定加盟共和国有退出权、设联盟苏维埃与民族苏维埃两院。",impact:"联盟国家把党的等级结构与联邦形式焊接起来，其民族划界与退出权条款在1991年成为解体的法理入口；对外则使「苏联」成为国际体系中的新主体。",figures:["列宁","斯大林","布登·姆季瓦尼"],place:"莫斯科（大剧院）",state:"苏维埃社会主义共和国联盟",sources:["《苏联成立宣言》与《联盟条约》正文（1922年12月30日）","《第一次全苏苏维埃代表大会记录》（1922）"],tags:["联盟国家","宪法","民族划界"]},related:["world--1924--f01"]},
  {id:"world--1922--c01",track:"world",year:1922,yearApprox:false,dim:"culture",weight:3,title:"《尤利西斯》初版发行",summary:"乔伊斯小说在巴黎出版，引发审查与形式革命。",detail:{background:"小说1918至1920年在纽约《小评论》杂志连载，因其中章节被控淫秽而中止，出版商相继却步。",process:"1922年2月2日（书中主人公布卢姆的日子开始之日），莎士比亚书店以蓝色封面印行一千册初版；1933年12月美国联邦上诉法院在「美国诉兰登书局案」中裁定该书非淫秽，1934年纽约出版全本文。",impact:"意识流、文体拼贴与荷马对应结构成为现代主义小说的技术坐标；围绕该书的诉讼也重塑了英美出版审查的判例标准。",figures:["詹姆斯·乔伊斯","西尔维娅·比奇","埃兹拉·庞德"],place:"法国巴黎（莎士比亚书店）",state:"爱尔兰／法国／美国",sources:["《尤利西斯》1922年巴黎初版本","Richard Ellmann, James Joyce（1959）"],tags:["现代主义","出版审查","小说"]},related:[]},
  {id:"world--1922--c02",track:"world",year:1922,yearApprox:false,dim:"culture",weight:3,title:"图坦卡蒙墓墓室开启",summary:"卡特在帝王谷打开几乎未被盗掘的王陵。",detail:{background:"1917年起卡特在卡纳冯伯爵资助下系统清理帝王谷，1922年11月4日发现通向石阶。",process:"11月26日在封泥门墙开洞，借烛光窥见镀金雕像与家具；1923年2月16日开启葬仪室，1924年完成前厅清理；墓中五千余件遗物按层级编号运往开罗博物馆，1925年11月始启石棺。",impact:"这是埃及学史上唯一近乎完整的法老葬具组合，其材料与记录成为此后考古发掘与文物保护流程的参照；同时引发关于文物归属与「法老诅咒」传媒炒作的首轮争议。",figures:["霍华德·卡特","卡纳冯伯爵","皮埃尔·拉科"],place:"埃及卢克索帝王谷",state:"埃及（英国委任统治时期）",sources:["霍华德·卡特《图坦卡蒙陵墓》三卷本（1933）及现场笔记","Pierre Lacau 1923年埃及文物局公报"],tags:["考古","文物","埃及学"]},related:[]},
{id:"world--1923--p01",track:"world",year:1923,yearApprox:false,dim:"politics",weight:4,title:"《洛桑条约》签订",summary:"安卡拉政府以战场既成事实推翻色佛尔方案，重定土耳其边界。",detail:{background:"《色佛尔条约》把东色雷斯、伊兹密尔与海峡区交由协约国处置，安卡拉议会拒绝批准并继续作战。",process:"会议自1922年11月起断续进行，土耳其以收复东色雷斯与海峡区为筹码，1923年7月24日与各方签署条约。",impact:"条约废除治外法权与财政管制，取消亚美尼亚与库尔德自治安排，以人口交换换取边界承认，成为凡尔赛体系在东南欧的修正。",figures:["伊斯梅特·伊诺努","乔治·寇松","阿里斯蒂德·白里安"],place:"瑞士洛桑",state:"土耳其大国民议会／英法意希等缔约国",sources:["1923年7月24日《洛桑条约》正文","土耳其大国民议会1923年8月批准记录"],tags:["战后条约","土耳其","主权"]},related:["world--1920--p03"]},
{id:"world--1923--e01",track:"world",year:1923,yearApprox:false,dim:"economy",weight:3,title:"德国恶性通胀到达顶点",summary:"鲁尔被占后以印钞支付消极抵抗经费，马克汇价跌至万亿量级。",detail:{background:"法比军队1923年1月出兵鲁尔，德国政府号召消极抵抗，并以国库券垫付停工工资与税收损失。",process:"1923年11月汇价跌至约4.2万亿马克兑1美元，物价以小时计价；政府停发抵抗经费，11月15日推行地租马克。",impact:"通胀使储蓄与公债持有者近乎清零，中产阶层对议会体制离心，也为外国贷款主导的重建打开门。",figures:["亚尔马·沙赫特","古斯塔夫·施特雷斯曼","雷蒙·普恩加来"],place:"德国鲁尔区、柏林",state:"魏玛共和国／法国／比利时",sources:["费尔德曼《大失序：德国通胀时期的政治与社会（1914—1924）》","1923年11月德国货币改革法令与地租马克发行条例"],tags:["恶性通胀","鲁尔危机","魏玛共和国"]},related:["world--1923--p01"]},
{id:"world--1923--d01",track:"world",year:1923,yearApprox:false,dim:"disaster",weight:3,title:"关东大地震与东京火风暴",summary:"震级约7.9的地震引发火风暴，烧毁东京与横滨大片木造市街。",detail:{background:"东京与横滨的木造连片住宅、狭窄街巷与盛夏干燥条件，使震后火灾成为主要致死原因。",process:"1923年9月1日上午地震发生，午后多处火场合为火风暴；东京府与神奈川县实施戒严，军队分区承担救灾与供水。",impact:"官方调查所载死难与失踪约10.5万人，另有逾14万的估算（属估算）；震后谣言引发对朝鲜人、华工与激进者的私刑杀害，十年复兴计划使东京转向混凝土道路与大街区格局。",figures:["后藤新平","山本权兵卫"],place:"日本东京府、神奈川县",state:"日本",sources:["内务省震灾预防对策调查委员会《大正震灾预防对策调查报告书》（1925年）","东京市复兴局1923年灾后复兴计划文书"],tags:["地震","城市防灾","日本"]},related:[]},
{id:"world--1923--s01",track:"world",year:1923,yearApprox:false,dim:"science",weight:3,title:"德布罗意提出物质波假说",summary:"把光量子的波粒二象性推广到电子，给出动量与波长对应关系。",detail:{background:"玻尔的量子化条件缺乏力学基础，光电效应与康普顿散射使波动性与粒子性并存的图景浮现。",process:"1923年他在法国《科学院院报》连续提交短文，写下波长等于普朗克常量除以动量；1924年博士论文给出系统论证。",impact:"假说在1927年由电子衍射实验验证，直接引导薛定谔建立波动力学，德布罗意获1929年诺贝尔物理学奖。",figures:["路易·德布罗意","尼尔斯·玻尔","阿尔伯特·爱因斯坦"],place:"法国巴黎",state:"法兰西第三共和国",sources:["法国《科学院院报》1923年所载德布罗意系列短文","德布罗意《量子理论研究》（1924年巴黎大学博士论文）"],tags:["量子力学","波粒二象性","物质波"]},related:[]},
{id:"world--1924--f01",track:"world",year:1924,yearApprox:false,dim:"figure",weight:3,title:"列宁逝世与第一部苏联宪法",summary:"联盟成立次年后，宪法把条约式联合固定为联邦建制。",detail:{background:"1922年四共和国以条约结成联盟，列宁晚年关于大国沙文主义与机关官僚化的信件未被公开。",process:"列宁自1922年中风后逐步失去活动能力，1924年1月21日去世；1月31日第二次全苏苏维埃大会通过联盟宪法基础条款。",impact:"宪法写明加盟共和国的退出权与民族划界原则，此后在党内继承斗争中被反复援引，也反复被搁置。",figures:["弗拉基米尔·列宁","约瑟夫·斯大林","列夫·托洛茨基","格里戈里·季诺维也夫"],place:"莫斯科（哥尔克庄园、红场）",state:"苏维埃社会主义共和国联盟",sources:["《苏维埃社会主义共和国联盟宪法（基础条款）》1924年1月31日文本","列宁《给代表大会的信》（1922—1923年，1956年苏共二十大后部分公开）"],tags:["苏联成立","宪法","继承"]},related:["world--1922--p03"]},
{id:"world--1924--p01",track:"world",year:1924,yearApprox:false,dim:"politics",weight:3,title:"马泰奥蒂被杀与阿文丁退出",summary:"社会党议员调查选举舞弊后遭绑架杀害，反对派退出国会。",detail:{background:"1924年4月大选在《阿切尔比法》的名单奖励制下进行，反对党指控胁迫投票与计票舞弊。",process:"5月30日马泰奥蒂在罗马被法西斯人员绑架并杀害；6月27日起统一社会党等团体退出议会，即阿文丁退出。",impact:"反对派缺席使法西斯以护宪名义巩固多数，1925年1月3日墨索里尼公开担责，一党专政程序由此展开。",figures:["贾科莫·马泰奥蒂","贝尼托·墨索里尼","乔瓦尼·阿门多拉"],place:"意大利罗马、菲亚诺罗马诺",state:"意大利王国",sources:["1923年4月意大利《阿切尔比选举法》文本","墨索里尼1925年1月3日众议院演说记录"],tags:["法西斯主义","议会危机","政治暗杀"]},related:["world--1922--p02"]},
{id:"world--1924--p02",track:"world",year:1924,yearApprox:false,dim:"politics",weight:3,title:"大国民议会废除哈里发制",summary:"素丹制终结一年后，议会取消哈里发并放逐奥斯曼家族。",detail:{background:"1922年11月素丹制废除后，哈里发仍作为宗教象征留存，形成安卡拉与伊斯坦布尔的双重权威。",process:"1924年3月3日一揽子法律废除哈里发、撤销宗教基金部与教法审判体系，奥斯曼家族成员限期离境。",impact:"世俗法制改革扫清了凯末尔主义在法律上的障碍，也激起印度等地哈里发运动的余波与其失败。",figures:["穆斯塔法·凯末尔","伊斯梅特·伊诺努","阿卜杜勒-梅吉德二世"],place:"土耳其安卡拉",state:"土耳其大国民议会政府",sources:["土耳其大国民议会1924年3月3日废除哈里发与统一教法等七项法律","1924年土耳其宪法文本"],tags:["政教分离","凯末尔改革","哈里发"]},related:["world--1923--p01"]},
{id:"world--1924--e01",track:"world",year:1924,yearApprox:false,dim:"economy",weight:3,title:"道威斯计划重开德国偿付",summary:"以国际贷款、交通担保与递增赔款表恢复德国偿付能力。",detail:{background:"1923年通胀与鲁尔对抗使赔款实际停付，法比占领成本上升，美国成为欧洲债务与复兴的枢纽。",process:"1924年4月专家委员会报告提出国际贷款并以交通与工业收益担保；8月伦敦会议批准后德国恢复交付。",impact:"计划使美资回流欧洲、短暂稳定马克与物价，也把德国偿付能力与纽约信贷周期绑在一起。",figures:["查尔斯·道威斯","古斯塔夫·施特雷斯曼","卡尔·哈文施泰因"],place:"英国伦敦、德国柏林",state:"魏玛共和国／协约国赔款委员会",sources:["1924年道威斯专家委员会报告与伦敦议定书文本","1924年8月30日德国《新债券法》"],tags:["赔款","国际贷款","货币稳定"]},related:["world--1923--e01"]},
{id:"world--1925--p01",track:"world",year:1925,yearApprox:false,dim:"politics",weight:4,title:"洛迦诺公约与西欧边界保证",summary:"德法比英意相互保证西部边界，东部争议改走仲裁程序。",detail:{background:"道威斯计划后法比从鲁尔撤军，施特雷斯曼与白里安寻求以边界保证换取德国重返欧洲体系。",process:"1925年10月在洛迦诺谈判、12月1日在斯特拉斯堡互换批准书，形成西部保证、东部仲裁与法波、法德互助等七份文件。",impact:"公约带来洛迦诺精神与德国加入国联之路，但对东部边界的松散处理为1930年代的修正留下缺口。",figures:["古斯塔夫·施特雷斯曼","阿里斯蒂德·白里安","奥斯汀·张伯伦","贝尼托·墨索里尼"],place:"瑞士洛迦诺、法国斯特拉斯堡",state:"德国／法国／比利时／英国／意大利",sources:["1925年12月1日斯特拉斯堡互换的洛迦诺公约七份文件","国际联盟条约汇编收录的洛迦诺文本"],tags:["集体安全","边界保证","魏玛德国"]},related:["world--1924--e01"]},
{id:"world--1925--p02",track:"world",year:1925,yearApprox:false,dim:"politics",weight:3,title:"墨索里尼宣布一党执政责任",summary:"承当政治与道德责任，独立报刊与工会自由随之被取消。",detail:{background:"马泰奥蒂案后阿文丁退出使议会失去质询主体，法西斯小队继续在地方施暴。",process:"1925年1月3日墨索里尼在众议院承当政治、道德与历史责任，随后新闻审查、集会限制与特别法庭相继设立。",impact:"1925至1926年的系列特别法取消工会权利与地方民选，意大利成为欧洲第一个法西斯一党国。",figures:["贝尼托·墨索里尼","乔瓦尼·阿门多拉","安东尼奥·格拉姆西"],place:"意大利罗马",state:"意大利王国",sources:["墨索里尼1925年1月3日众议院演说全文（《墨索里尼全集》）","1926年意大利特别法（所谓法西斯法）文本"],tags:["一党国","新闻审查","法西斯主义"]},related:["world--1924--p01"]},
{id:"world--1925--s01",track:"world",year:1925,yearApprox:false,dim:"science",weight:3,title:"海森堡创立矩阵力学",summary:"只用可观测量与表格运算重建力学，量子论第一种完备形式。",detail:{background:"玻尔对应原理与索末菲量子化规则在氦原子与谱线强度问题上接连失效。",process:"1925年7月海森堡在赫尔戈兰岛避暑期间完成论文草稿，玻恩与约尔当将其改写为矩阵表述并补入对易关系。",impact:"矩阵力学与次年薛定谔波动力学被证明等价，物理从此放弃电子轨道图像，不确定性原理也有了数学框架。",figures:["维尔纳·海森堡","马克斯·玻恩","帕斯库尔·约尔当","沃尔夫冈·泡利"],place:"德国赫尔戈兰岛、哥廷根",state:"魏玛共和国",sources:["海森堡《关于量子理论对运动学与力学关系的重新诠释》（1925年）","玻恩与约尔当《关于量子力学》（1925年）"],tags:["量子力学","矩阵","可观测量"]},related:["world--1923--s01"]},
{id:"world--1925--a01",track:"world",year:1925,yearApprox:false,dim:"art",weight:3,title:"巴黎国际现代装饰与工业艺术博览会",summary:"装饰艺术风格由此得名，几何化手工艺与现代主义展馆同台。",detail:{background:"战后法国工艺与工业界争夺现代风格的定义权，政府希望以博览会重振设计出口与声誉。",process:"1925年4月至10月在巴黎塞纳河沿岸展馆举行，约20国参与，按国别展馆与材料行会分区布置。",impact:"博览会命名的装饰艺术成为1930年代消费美学主流，柯布西耶的新精神展馆则把争论引向现代建筑。",figures:["勒·柯布西耶","艾琳·格雷"],place:"法国巴黎",state:"法兰西第三共和国",sources:["1925年巴黎国际现代装饰与工业艺术博览会官方总图录","勒·柯布西耶《我们时代的装饰艺术》（1925年）"],tags:["设计史","装饰艺术","现代主义"]},related:[]},
{id:"world--1926--i01",track:"world",year:1926,yearApprox:false,dim:"institution",weight:3,title:"德国加入国际联盟",summary:"洛迦诺体系落地，德国获得理事会常任席位。",detail:{background:"公约批准、国内反条约公投失败之后，国联理事会同意德国以常任席入盟。",process:"1926年9月8日国联大会通过扩大理事会的安排，德国随后在裁军委员会问题上与法国陷入僵持。",impact:"联盟暂时摆脱战胜国俱乐部的色彩，但其决议仍受英法一致与国内否决约束，1933年德国退出。",figures:["古斯塔夫·施特雷斯曼","罗伯特·塞西尔"],place:"瑞士日内瓦（国联总部）",state:"国际联盟／德国",sources:["国际联盟大会1926年9月关于扩大理事会的决议记录","《国际联盟盟约》正文"],tags:["集体安全","国际联盟","魏玛德国"]},related:["world--1925--p01"]},
{id:"world--1926--p01",track:"world",year:1926,yearApprox:false,dim:"politics",weight:3,title:"英国九日总罢工",summary:"工会联合会号召全国停工支持矿工，政府以志愿供给队维持秩序。",detail:{background:"1925年红色星期五的临时补贴到期，萨缪尔委员会建议下调矿工工资并反对回到战前金平价。",process:"1926年5月3日至12日运输、印刷、钢铁等部门停止工作，政府动员志愿供给队与军队维持食品与报纸流通。",impact:"罢工瓦解后工会实力受挫，1927年《劳资争议法》禁止政治性总罢工，工党此后转向议会道路。",figures:["斯坦利·鲍尔温","欧内斯特·贝文","阿瑟·库克"],place:"英国伦敦、威尔士南部矿区",state:"英国",sources:["萨缪尔皇家调查委员会报告（1926年3月）","1927年英国《劳资争议法》文本"],tags:["总罢工","工会","英国工运"]},related:[]},
{id:"world--1926--s01",track:"world",year:1926,yearApprox:false,dim:"science",weight:3,title:"薛定谔建立波动力学",summary:"把原子态解为波动方程的本征函数，量子化成为本征值问题。",detail:{background:"德布罗意的物质波需要一套能解释谱线强度的波动理论，爱因斯坦关于单原子气体量子的论文提供了刺激。",process:"1926年1至6月薛定谔在《物理年鉴》连发四篇《量子化作为本征值问题》，重算出氢原子能级。",impact:"波动力学因数学工具成熟而迅速取代矩阵表述，同年他与海森堡围绕理论的直观性展开争论。",figures:["埃尔温·薛定谔","路易·德布罗意","阿尔伯特·爱因斯坦","维尔纳·海森堡"],place:"瑞士苏黎世",state:"瑞士联邦",sources:["薛定谔《量子化作为本征值问题》（《物理年鉴》1926年第79至80卷）","德布罗意《量子理论研究》（1924年）"],tags:["波动力学","本征值","量子力学"]},related:["world--1925--s01"]},
{id:"world--1926--p02",track:"world",year:1926,yearApprox:false,dim:"politics",weight:3,title:"毕苏茨基五月政变",summary:"议会僵局中毕苏茨基率部进逼华沙，建立强总统体制。",detail:{background:"波兰议会联合政府频繁更替，1925年后外交预算与土改僵局使行政部门无力推进。",process:"1926年5月12日至14日毕苏茨基自华沙郊外率部进逼，政府方面指挥者西科尔斯基拒绝交战，总统出走。",impact:"同年8月修宪确立强总统制，1930年布列斯特监禁反对派后波兰进入威权的萨纳齐亚时期。",figures:["约瑟夫·毕苏茨基","斯坦尼斯瓦夫·沃伊切霍夫斯基","瓦迪斯瓦夫·西科尔斯基"],place:"波兰华沙",state:"波兰共和国",sources:["1926年波兰八月宪法修正案文本","1926年5月波兰政府与总统府公告文件"],tags:["政变","强总统制","波兰"]},related:["world--1920--p02"]},
{id:"world--1927--s01",track:"world",year:1927,yearApprox:false,dim:"science",weight:3,title:"索尔维会议与不确定性原理",summary:"量子力学的测量之争在此定调，玻尔与爱因斯坦正面交锋。",detail:{background:"矩阵力学与波动力学被证明等价之后，海森堡提出测不准关系，泡利的不相容原理也已问世。",process:"1927年10月下旬在布鲁塞尔举行的第五届索尔维会议以电子与光子为题，玻尔以追拍缝隙思想实验回击爱因斯坦的质疑。",impact:"互补性由此成为哥本哈根诠释的核心表述，测量与实在的关系自此成为物理学与哲学的长期争点。",figures:["尼尔斯·玻尔","阿尔伯特·爱因斯坦","维尔纳·海森堡","沃尔夫冈·泡利"],place:"比利时布鲁塞尔",state:"比利时王国",sources:["《电子与光子：第五届索尔维会议报告与讨论》（1928年巴黎刊本）","海森堡《关于量子力学机械解释的不确定性问题》（1927年）"],tags:["量子力学","测量","哥本哈根诠释"]},related:["world--1925--s01"]},
{id:"world--1927--p01",track:"world",year:1927,yearApprox:false,dim:"politics",weight:3,title:"日内瓦海军军备会议失败",summary:"美英就巡洋舰比例僵持，法意拒绝接受约束，裁军链条断裂。",detail:{background:"1922年华盛顿条约只限定主力舰与航空母舰比例，巡洋舰与驱逐舰的吨位与火炮口径悬而未决。",process:"1927年6至8月美英法意日五国在日内瓦与会，美国要求巡洋舰总吨位与英国平等，法国坚持自主安全，会议无决议闭幕。",impact:"会议失败使1930年伦敦海军条约只能在更低标准上达成，也强化了日本海军派以条约屈辱为由干预外交的论调。",figures:["弗兰克·凯洛格","奥斯汀·张伯伦"],place:"瑞士日内瓦",state:"美国／英国／法国／意大利／日本",sources:["美国国务院1927年日内瓦海军会议提案与全体会议记录","1922年《九国公约》与《限制海军军备条约》正文"],tags:["海军军备","华盛顿体系","裁军"]},related:[]},
{id:"world--1927--c01",track:"world",year:1927,yearApprox:false,dim:"culture",weight:3,title:"《大都会》首映与表现主义电影",summary:"巨型布景与机械人形象写下工业城市的反乌托邦。",detail:{background:"魏玛初期外资进入使德国电影得以大规模制片，乌发公司在巴贝尔斯贝格建成摄影棚群。",process:"1927年1月10日在柏林首映，布景、特效与群演规模空前，由乌发与美资贷款分担成本，片长超过两小时半。",impact:"影片的商业亏损终结了以巨额单片撑市场的模式，其城市景观与机械人形象成为二十世纪科幻视觉的原型。",figures:["弗里茨·朗","特娅·冯·哈博"],place:"德国柏林（巴贝尔斯贝格摄影棚）",state:"魏玛共和国",sources:["乌发电影公司1926至1927年制片与发行账目文件","《大都会》1927年德国首映版演职员表与审查批文"],tags:["表现主义","电影史","魏玛文化"]},related:["world--1929--c01"]},
{id:"world--1927--m01",track:"world",year:1927,yearApprox:false,dim:"military",weight:3,title:"桑地诺抗美游击战开始",summary:"拒绝美国监护下的选举安排，退入北部山区打持久游击。",detail:{background:"1912年以来美军驻在尼加拉瓜，1926年自由党与保守党政权内争中美国海军陆战队再次登陆。",process:"1927年9月桑地诺拒绝在美军监督下放下武器，率部退入塞戈维亚斯山区，以主权或死亡为口号开展游击。",impact:"三年游击使美国在1933年撤军并留下国民警卫队体制，桑地诺1934年遇刺后成为拉美反干涉运动的象征。",figures:["奥古斯托·桑地诺","亨利·史汀生"],place:"尼加拉瓜塞戈维亚斯山区",state:"尼加拉瓜／美国占领当局",sources:["1927年9月《埃斯皮诺贝尔德协定》文本与桑地诺拒绝签署的声明","美国海军陆战队1927至1933年尼加拉瓜行动年度报告"],tags:["游击战","反干涉","拉丁美洲"]},related:[]},
{id:"world--1928--s01",track:"world",year:1928,yearApprox:false,dim:"science",weight:4,title:"弗莱明发现青霉素",summary:"污染皿中出现抑菌圈，他判断其中含有可杀菌的物质。",detail:{background:"1920年代抗菌化疗研究活跃，弗莱明此前关于溶菌酶的工作为其提供了观察方法。",process:"1928年9月圣玛丽医院实验室中一只葡萄球菌培养皿被青霉菌污染，他记录菌落溶解并在1929年发表论文。",impact:"提纯与量产延至1940年代初由钱恩、弗洛里在牛津完成，1943年后盟军战场使用使创伤感染死亡率大幅下降。",figures:["亚历山大·弗莱明","霍华德·弗洛里","恩斯特·钱恩"],place:"英国伦敦（圣玛丽医院）",state:"英国",sources:["弗莱明《关于青霉菌培养物的抗菌作用及其在眼传染等疾病中的意义》（《英国实验病理学杂志》1929年第10卷）","牛津大学邓恩病理学院1940至1941年青霉素提纯实验记录"],tags:["抗生素","细菌学","医学史"]},related:["world--1921--s01"]},
{id:"world--1928--p01",track:"world",year:1928,yearApprox:false,dim:"politics",weight:3,title:"《非战公约》在巴黎签署",summary:"十五国宣布放弃以战争作为国家政策工具，却无制裁条款。",detail:{background:"日内瓦海军会议失败与法美仲裁条约争执之后，凯洛格与白里安互换了放弃战争的合作建议。",process:"1928年8月27日十五国在巴黎签署总公约，条约不设制裁机制；苏联在附加照会中要求在其与缔约国之间先行生效。",impact:"公约未能阻止1931年至1939年的侵略，但把战争的合法性问题推入国际法，成为纽伦堡审判的规范依据之一。",figures:["弗兰克·凯洛格","阿里斯蒂德·白里安"],place:"法国巴黎",state:"美国／法国／英国等十五缔约国",sources:["1928年《关于废弃以战争作为国家政策工具的一般条约》正文与生效照会","国际联盟条约汇编收录之本约文本"],tags:["国际法","裁军","集体安全"]},related:["world--1927--p01"]},
{id:"world--1928--s02",track:"world",year:1928,yearApprox:false,dim:"science",weight:3,title:"狄拉克方程与反物质预言",summary:"把量子论与狭义相对论结合，负能解指向正电子。",detail:{background:"泡利不相容原理与电子自旋假说提出后，仍缺一个相对论性的电子波动方程。",process:"1928年他在《皇家学会会刊》发表线性化的电子方程，自然导出自旋与磁矩比值，并留下负能解的难题。",impact:"负能解在1931年被解释为反电子，1932年安德森在宇宙线中观测到正电子，反物质从此进入实验物理。",figures:["保罗·狄拉克","沃尔夫冈·泡利"],place:"英国剑桥",state:"英国",sources:["狄拉克《电子的量子理论》（《皇家学会会刊》A辑第117卷，1928年）","泡利《论氢原子的量子力学》（1926年）"],tags:["理论物理","相对论量子力学","反物质"]},related:["world--1926--s01"]},
{id:"world--1928--e01",track:"world",year:1928,yearApprox:false,dim:"economy",weight:3,title:"苏联粮食收购危机与非常措施",summary:"为出口粮食与供应城市，中央以刑法手段强制征购余粮。",detail:{background:"新经济政策后期城市供应紧张、工农业产品价格剪刀差扩大，国家收购计划连续落空。",process:"1928年1月中央向西伯利亚与乌拉尔派出特别工作队，援引刑法第一百零七条打击存粮与拒售者，秋季转向义务征购。",impact:"非常措施中断了农村的市场交换，为1929年底的全面集体化与1932至1933年的大饥荒铺定路径。",figures:["约瑟夫·斯大林","拉扎尔·卡冈诺维奇"],place:"苏联西伯利亚西部、乌拉尔",state:"苏维埃社会主义共和国联盟",sources:["联共（布）中央1928年关于粮食收购的决议与刑法第一百零七条适用指示","苏联中央统计局1928至1929年粮食收购与播种面积统计汇编"],tags:["集体化","粮食征购","苏联经济"]},related:["world--1924--f01"]},
{id:"world--1929--e01",track:"world",year:1929,yearApprox:false,dim:"economy",weight:5,title:"华尔街股灾与大萧条开端",summary:"恐慌性抛售击穿保证金链条，信贷收缩迅速波及实业与欧洲。",detail:{background:"保证金交易与分期消费把投机推向顶峰，1929年秋美联储收紧贴现，英国经济已先陷疲态。",process:"10月24日纽约出现恐慌性抛售，29日单日成交约一千六百三十万股；银行收回对欧洲的短期贷款，物价与产出随后连年下坠。",impact:"到1933年美国工业产出与批发物价各下降约三分之一，失业大规模攀升，金本位与赔款体系随之解体。",figures:["赫伯特·胡佛","查尔斯·米切尔"],place:"美国纽约（华尔街）",state:"美国",sources:["美国参议院1932至1933年银行与货币委员会听证记录（皮科拉听证）","美国联邦储备委员会1929至1933年年度报告"],tags:["股灾","大萧条","金融监管"]},related:["world--1924--e01"]},
{id:"world--1929--p01",track:"world",year:1929,yearApprox:false,dim:"politics",weight:3,title:"杨格计划与莱茵兰撤军时间表",summary:"以约一千一百三十亿金马克、五十九年分期取代道威斯表。",detail:{background:"道威斯体系下德国偿付随繁荣攀升，法德就撤军时间与赔偿总额重新谈判。",process:"1929年6月杨格专家委员会提出报告，8月巴黎会议通过，1930年6月海牙协定落实国际清算银行与分阶段撤军安排。",impact:"计划把赔款与政治条款分离，助长了德国民族主义的抗议运动；大萧条后的延期偿付使其实际失效。",figures:["欧文·杨格","古斯塔夫·施特雷斯曼","阿里斯蒂德·白里安"],place:"法国巴黎、荷兰海牙",state:"德国／法国／英国／比利时等缔约国",sources:["1929年杨格专家委员会报告与1930年6月《海牙协定》文本","国际清算银行1930年成立章程"],tags:["赔款","国际清算银行","莱茵兰撤军"]},related:["world--1925--p01"]},
{id:"world--1929--p02",track:"world",year:1929,yearApprox:false,dim:"politics",weight:3,title:"托洛茨基被驱逐出境",summary:"左翼反对派失败后，他被押出边境并于1932年撤销国籍。",detail:{background:"1927年党把托洛茨基与季诺维也夫开除出党，1928年1月托洛茨基被流放至阿拉木图。",process:"1929年1月20日他从阿拉木图被押走，经巴统出境，2月抵达君士坦丁堡；1932年2月被撤销苏联国籍。",impact:"驱逐终结了党内的公开路线争论，1936至1938年的三次审判以反苏中心的罪名清算其追随者。",figures:["列夫·托洛茨基","约瑟夫·斯大林"],place:"苏联阿拉木图、土耳其君士坦丁堡",state:"苏维埃社会主义共和国联盟",sources:["1932年2月苏联中央执行委员会关于撤销托洛茨基国籍的决定","托洛茨基《被背叛的革命》（1936年）所记流亡经历"],tags:["党内斗争","流亡","苏联政治"]},related:["world--1924--f01"]},
{id:"world--1929--i01",track:"world",year:1929,yearApprox:false,dim:"institution",weight:3,title:"《拉特兰条约》与梵蒂冈城国",summary:"意大利承认教廷主权与天主教国教地位，教宗承认罗马首都。",detail:{background:"1870年教宗国并入意大利后，罗马问题使历届政府与圣座近六十年互不承认。",process:"1929年2月11日墨索里尼与加斯帕里枢机签署条约、专约与财政协定三份文件，同年5月经意大利议会批准。",impact:"条约换来政权在天主教徒中的合法性，也建立起延续至今的梵蒂冈城国与政教专约体制。",figures:["贝尼托·墨索里尼","皮耶特罗·加斯帕里","庇护十一世"],place:"罗马拉特兰宫、梵蒂冈",state:"意大利王国／圣座",sources:["1929年2月11日《拉特兰条约》三文件正文（条约、专约与财政协定）","庇护十一世1931年5月通谕《我们并不需要》"],tags:["政教关系","梵蒂冈","法西斯意大利"]},related:["world--1925--p02"]},
{id:"world--1929--s01",track:"world",year:1929,yearApprox:false,dim:"science",weight:3,title:"哈勃发现星系退行与距离关系",summary:"星系红移与距离成正比，宇宙膨胀成为观测事实。",detail:{background:"大口径望远镜使仙女座等星云的距离得以确定，弗里德曼与勒梅特已从方程给出膨胀解。",process:"1929年他把斯利弗的红移数据与自己测定的距离并列，给出每百万秒差距约五百公里的退行比例。",impact:"膨胀的观测把静态宇宙模型送进历史，也让宇宙年龄与尺度成为物理学的中心议题。",figures:["埃德温·哈勃","维斯托·斯利弗","乔治·勒梅特"],place:"美国威尔逊山天文台",state:"美国",sources:["哈勃《河外星云的距离与径向速度关系》（《美国国家科学院院报》第15卷，1929年）","斯利弗1912至1925年星云径向速度观测汇编"],tags:["宇宙学","红移","观测天文"]},related:[]},
{id:"world--1929--c01",track:"world",year:1929,yearApprox:false,dim:"culture",weight:3,title:"《西线无战事》出版与畅销",summary:"以普通士兵视角重写堑壕经验，当年即被译为数十种语言。",detail:{background:"1920年代欧洲围绕大战记忆展开论争，前线叙事与官方悼亡话语逐渐分裂。",process:"1929年1至3月报纸连载，10月由乌尔施泰因出版单行本，当年登上畅销榜并被译成二十余种语言。",impact:"小说与1930年改编电影成为反战记忆的国际符号，也在德国民族主义阵营中激起背叛前线的攻击。",figures:["埃里希·玛丽亚·雷马克"],place:"德国柏林",state:"魏玛共和国",sources:["乌尔施泰因出版社1929年《西线无战事》初版本","1930年德国各邦电影审查与禁映档案"],tags:["战争文学","大战记忆","出版史"]},related:["world--1927--c01"]},
{id:"world--1930--p01",track:"world",year:1930,yearApprox:false,dim:"politics",weight:4,title:"甘地发起食盐长征",summary:"沿海步行约三百九十公里，以自产食盐对抗盐税与专卖。",detail:{background:"1929年国大党拉合尔年会把完全独立提上日程，盐税的累退性与食盐专卖使它成为低成本的动员点。",process:"1930年3月12日至4月6日甘地自艾哈迈达巴德步行至丹迪取盐，此后数月出现抗税、接管盐仓与和平罢市。",impact:"英方公报所载逮捕数以万计（属估算），运动迫使英国承认国大党为谈判对手，圆桌会议由此开启。",figures:["莫罕达斯·甘地","爱德华·伍德","西德尼·韦布"],place:"印度古吉拉特邦沿海（艾哈迈达巴德至丹迪）",state:"英属印度",sources:["1930至1931年印度政府关于食盐运动与逮捕人数的公报","《甘地全集》（新德里，1927年起刊行）所载1930年致欧文函"],tags:["非暴力抵抗","食盐税","印度独立"]},related:["world--1920--p02"]},
{id:"world--1930--p02",track:"world",year:1930,yearApprox:false,dim:"politics",weight:3,title:"布吕宁总统制与纳粹进入国会",summary:"议会多数无法组阁，以紧急法令治国成为惯例。",detail:{background:"1930年3月布吕宁接任总理时社民党已不入阁，议会中反议会的政党合计占多数。",process:"预算案在7月被否决后，总统依宪法第四十八条发布紧急法令；9月14日大选中纳粹党获得一百零七席。",impact:"紧急法令的先例把行政权移到总统与总理周围，为1932至1933年的总统内阁铺路。",figures:["海因里希·布吕宁","保罗·冯·兴登堡","阿道夫·希特勒"],place:"德国柏林",state:"魏玛共和国",sources:["帝国统计局1930年9月14日联邦大选结果汇编","1930年7月德国预算紧急法令文本"],tags:["总统内阁","紧急法令","纳粹党"]},related:["world--1925--p02"]},
{id:"world--1930--e01",track:"world",year:1930,yearApprox:false,dim:"economy",weight:3,title:"美国通过斯穆特—霍利关税法",summary:"把数千种进口品税率推向高位，触发各国连锁报复。",detail:{background:"大萧条后美国农产品与工业品价格齐跌，国会以保护国内就业为名推动加税。",process:"1930年6月17日法律签署生效，应税进口品的从价税率升至当时历史高位，千余名经济学家与商界人士联名请愿反对。",impact:"加拿大、英国与欧洲大陆相继报复，世界贸易额在三年内缩减近半，金本位下的多边清算更难维系。",figures:["赫伯特·胡佛","里德·斯穆特","威利斯·霍利"],place:"美国华盛顿",state:"美国",sources:["1930年6月17日美国《关税法》正文","1930年美国国会财政委员会听证记录与反对请愿书"],tags:["贸易保护","关税战","大萧条"]},related:["world--1929--e01"]},
{id:"world--1930--s01",track:"world",year:1930,yearApprox:false,dim:"science",weight:3,title:"汤博在洛厄尔台发现冥王星",summary:"以闪视比较仪在数月底片中认出移动的光点。",detail:{background:"洛厄尔据海王星外摄动预测存在第九行星，其去世后天文台在斯利弗主持下继续巡天。",process:"1930年2月18日汤博比对1月初拍摄的底片时认出位移点，3月13日洛厄尔台发出通报，海德堡与叶凯士台随后追认。",impact:"该天体1930年5月定名，1931年起国际天文界沿用；2006年被重分类为矮行星，标志以照相巡天寻找行星时代的结束。",figures:["克莱德·汤博","珀西瓦尔·洛厄尔","维斯托·斯利弗"],place:"美国亚利桑那州弗拉格斯塔夫（洛厄尔天文台）",state:"美国",sources:["洛厄尔天文台1930年3月13日关于新行星的通报电文","海德堡台与叶凯士台1930年追认观测记录"],tags:["天文发现","行星","照相巡天"]},related:["world--1929--s01"]},
{id:"world--1930--m01",track:"world",year:1930,yearApprox:false,dim:"military",weight:2,title:"协约国军队提前撤出莱茵兰",summary:"占领与军事管制终止，凡尔赛体系失去一条外部约束。",detail:{background:"《凡尔赛条约》规定分区占领、按期撤军，1929年杨格计划把撤军与新的赔款表挂钩。",process:"1930年6月30日最后一批部队撤出科隆区，莱茵河左岸的占领与军事管制同时终止。",impact:"民族主义阵营把它宣传为自由战争的胜利，魏玛政府外部约束消失，军备与边界修正议题浮出水面。",figures:["古斯塔夫·施特雷斯曼","安德烈·塔尔迪厄"],place:"德国科隆、美因茨一带（莱茵河左岸）",state:"魏玛共和国／协约国占领军",sources:["1930年6月30日撤军实施公报与《海牙协定》文本","《凡尔赛条约》第十四条以下关于莱茵兰占领的规定"],tags:["莱茵兰撤军","凡尔赛体系","魏玛共和国"]},related:["world--1929--p01"]},
{id:"world--1931--e01",track:"world",year:1931,yearApprox:false,dim:"economy",weight:3,title:"奥地利信用银行倒闭触发银行危机",summary:"政府担保超出承受，挤兑两周内蔓延至德国与中欧。",detail:{background:"1929年后德国偿付与中欧债务依赖短期贷款，维也纳各大银行以国库担保承接坏账。",process:"1931年5月11日奥地利信用银行宣布无法偿付，政府连带担保义务暴露；随后挤兑与资本外逃波及柏林与布拉格。",impact:"6月的延期偿付建议与7月的英国报告接连出台，金本位在一年内解体，短期国际清算让位于外汇管制。",figures:["海因里希·布吕宁","拉姆齐·麦克唐纳"],place:"奥地利维也纳、德国柏林",state:"奥地利／德国／英国",sources:["1931年5月奥地利政府关于信用银行事件的公告与清算方案","1931年6月20日美国关于赔款与战债延期偿付的提案"],tags:["银行危机","资本外逃","金本位"]},related:["world--1930--e01"]},
{id:"world--1931--e02",track:"world",year:1931,yearApprox:false,dim:"economy",weight:3,title:"英国中止金本位与国民政府成立",summary:"削减支出建议引发工党内阁分裂，英镑随后脱离黄金。",detail:{background:"1931年夏英国黄金与外汇储备快速流失，国家支出委员会报告建议大幅削减失业救济与公职薪俸。",process:"8月24日内阁集体辞职，25日组成以麦克唐纳为首的国民政府；9月21日财政部停止英镑兑换黄金。",impact:"英镑贬值使英联邦与北欧率先复苏，压力转给美国与法国，1936年前各国以汇率集团相互对立。",figures:["拉姆齐·麦克唐纳","斯坦利·鲍尔温","乔治·梅"],place:"英国伦敦",state:"英国",sources:["国家支出皇家委员会1931年7月报告（梅委员会报告）","1931年9月21日英国财政部关于停止黄金支付的公告"],tags:["金本位","英镑","国民政府"]},related:["world--1931--e01"]},
{id:"world--1931--p01",track:"world",year:1931,yearApprox:false,dim:"politics",weight:3,title:"《威斯敏斯特法令》确立议会平等",summary:"自治领立法权脱离英国议会，共戴一君而各自独立。",detail:{background:"1926年帝国内部关系报告已界定自治领地位，爱尔兰自由邦与加拿大拒绝英国议会的上诉管辖。",process:"1931年12月11日英国议会通过法令，加拿大、澳大利亚、新西兰、南非、爱尔兰自由邦与纽芬兰取得平等立法权。",impact:"第二英帝国自此成为松散的法统联合体，澳大利亚与新西兰直到1942年才正式采纳该法令。",figures:["亚瑟·贝尔福","拉姆齐·麦克唐纳"],place:"英国伦敦（威斯敏斯特）",state:"英国／各自治领",sources:["1931年英国《威斯敏斯特法令》正文","1926年帝国内部关系会议报告（贝尔福报告）"],tags:["英联邦","自治领","立法权"]},related:["world--1926--p01"]},
{id:"world--1931--d01",track:"world",year:1931,yearApprox:false,dim:"disaster",weight:2,title:"马那瓜大地震",summary:"两次强震摧毁首都，美国驻军主导秩序与灾后选举。",detail:{background:"1927年以来桑地诺游击队活动扩大，美国在尼加拉瓜驻有海军陆战队并监护其财政。",process:"1931年3月31日两次强震袭击马那瓜，旧总统府与主教座堂倒塌，死难以千计（美方与救灾机构估算，属估算）。",impact:"灾后选举与美军撤出计划提速，1933年撤军后国民警卫队成为新的权力支点。",figures:["赫伯特·胡佛","奥古斯托·桑地诺"],place:"尼加拉瓜马那瓜",state:"尼加拉瓜／美国占领当局",sources:["1931年马那瓜地震的国际地震学会报告与损失统计","美国国务院1931年关于尼加拉瓜灾后选举的通报"],tags:["地震","尼加拉瓜","美国干涉"]},related:["world--1927--m01"]},
{id:"world--1932--p01",track:"world",year:1932,yearApprox:false,dim:"politics",weight:3,title:"国联调查团报告书发表",summary:"不承认满洲现状，同时承认日本在华特殊利益。",detail:{background:"1931年9月后关东军控制东北三省，1932年3月宣告成立满洲国，国联在12月派出调查团。",process:"以李顿为团长的调查团考察后，于1932年10月2日在日内瓦发表报告书，主张不承认既成事实并提出自治与国际顾问方案。",impact:"1933年2月24日国联大会以压倒多数通过不承认结论，日本于3月退出国联，集体安全机制首次失效。",figures:["维克多·李顿","顾维钧","罗伯特·范登海维尔"],place:"瑞士日内瓦（国联总部）、中国东北",state:"国际联盟／日本／中华民国",sources:["国联调查团《关于中日争议之报告书》（1932年10月2日）正文","国际联盟大会1933年2月24日表决记录"],tags:["满洲事变","不承认主义","国际联盟"]},related:["world--1928--p01"]},
{id:"world--1932--s01",track:"world",year:1932,yearApprox:false,dim:"science",weight:4,title:"查德威克发现中子",summary:"以反冲核测定能量，确认核内存在中性粒子。",detail:{background:"以α粒子轰击铍产生的高贯穿辐射，此前被博特、贝克尔与约里奥—居里夫妇判为γ射线。",process:"1932年2月他在卡文迪什实验室测量石蜡反冲质子能量，判定新粒子质量近于质子且不带电，3月投书《自然》。",impact:"中子不受库仑势垒阻挡，随即成为核反应与人工放射性研究的主要弹粒，1935年查德威克获诺贝尔物理学奖。",figures:["詹姆斯·查德威克","欧内斯特·卢瑟福","伊雷娜·约里奥—居里"],place:"英国剑桥（卡文迪什实验室）",state:"英国",sources:["查德威克《中子的可能存在》（《自然》第129卷，1932年）","约里奥—居里夫妇1932年关于石蜡反冲质子的院报通报"],tags:["核物理","中子","实验发现"]},related:["world--1928--s02"]},
{id:"world--1932--s02",track:"world",year:1932,yearApprox:false,dim:"science",weight:3,title:"安德森在宇宙线中发现正电子",summary:"云室轨迹弯向反电子一侧，反物质得到实验证据。",detail:{background:"狄拉克方程的负能解在1931年被解释为反电子，密立根团队正加强宇宙线观测以检验各类预言。",process:"1932年8月他在穿过铅板的云室照片中测得曲率与电离损失，判定该粒子质量近于电子而电荷相反。",impact:"正电子的发现把反物质带入实验物理，1936年安德森与发现宇宙线电离的赫斯分享诺贝尔物理学奖。",figures:["卡尔·安德森","保罗·狄拉克","罗伯特·密立根"],place:"美国帕萨迪纳（加州理工学院）",state:"美国",sources:["安德森《正电子》（《科学》第76卷，1932年）","布莱克特与奥基亚基尼1933年云室复现记录"],tags:["宇宙线","反物质","粒子物理"]},related:["world--1932--s01"]},
{id:"world--1932--e01",track:"world",year:1932,yearApprox:false,dim:"economy",weight:3,title:"洛桑会议终结德国赔款",summary:"把赔款降为一笔象征性清算，但美国拒绝承认债务抵销。",detail:{background:"1931年银行危机后德国已无力按杨格表付款，英法在美债与德款之间相互推诿。",process:"1932年6至7月洛桑会议同意以一笔三十亿马克的终期清算结束赔款，但该安排因美国反对从未生效。",impact:"1934年美国国会联合决议反对把欧债清算与战债偿付分离，赔款问题从此让位于军备与政治争端。",figures:["赫伯特·胡佛","弗朗茨·冯·帕彭","内维尔·张伯伦"],place:"瑞士洛桑",state:"德国／法国／英国／意大利",sources:["1932年7月8日洛桑会议议定书与三边换文文本","1934年美国国会关于战债偿付的联合决议文本"],tags:["赔款终结","洛桑会议","大萧条"]},related:["world--1929--p01"]},
{id:"world--1932--a01",track:"world",year:1932,yearApprox:false,dim:"art",weight:3,title:"包豪斯在德绍被关闭",summary:"地方议会停止拨款，末期的柏林阶段不足一年即终结。",detail:{background:"1930年密斯接任校长后经费缩减，1931年11月纳粹党进入德绍所在邦的地方议会。",process:"1932年9月30日德绍市议会通过停拨决议，10月校舍封闭；学校以私立形式迁往柏林，1933年自行解散。",impact:"师生流亡把功能主义与基础课程改革带入英国与美国，包豪斯成为二十世纪设计教育的代名词。",figures:["路德维希·密斯·凡·德·罗","瓦尔特·格罗皮乌斯","拉兹洛·莫霍利—纳吉"],place:"德国德绍、柏林",state:"魏玛共和国",sources:["德绍市议会1932年关于停止包豪斯拨款的决议记录","包豪斯1932至1933年柏林末期的解散声明与文件"],tags:["设计教育","包豪斯","魏玛文化"]},related:["world--1925--a01"]},
{id:"world--1933--p01",track:"world",year:1933,yearApprox:false,dim:"politics",weight:4,title:"希特勒受命出任德国总理",summary:"保守派阵线瓦解，兴登堡在一月三十日完成任命。",detail:{background:"1932年夏秋帕彭与施莱歇尔的内阁更替接连失败，11月大选后纳粹党跌到一百九十六席但仍为第一大党。",process:"1933年1月28日施莱歇尔辞职，30日上午兴登堡任命希特勒为总理，新内阁中纳粹党仅占三席。",impact:"保守派以为可以围住新总理，六周后《授权法》使魏玛宪法实质终结，欧洲最大工业国落入一党统治。",figures:["阿道夫·希特勒","保罗·冯·兴登堡","弗朗茨·冯·帕彭","库尔特·冯·施莱歇尔"],place:"德国柏林（帝国总理府）",state:"德国",sources:["1933年1月30日关于希特勒受命组阁的官方公告与内阁名单","帝国统计局1932年7月与11月大选结果汇编"],tags:["纳粹夺权","总统内阁","魏玛共和国"]},related:["world--1930--p02"]},
{id:"world--1933--p02",track:"world",year:1933,yearApprox:false,dim:"politics",weight:3,title:"国会纵火案与《授权法》",summary:"紧急条例中止公民权，三周后议会把立法权交给内阁。",detail:{background:"1933年2月新政府解散国会，选举期间冲锋队与警察在普鲁士同步清洗反对派机关与报刊。",process:"2月27日国会大厦起火，次日依宪法第四十八条颁布保护人民与国家条例；3月23日授权法在克罗尔歌剧院表决通过。",impact:"授权法使内阁得以自行立法并名义上延续至1945年，社民党投下唯一反对票，共产党议员已被禁止入席。",figures:["阿道夫·希特勒","赫尔曼·戈林","奥托·韦尔斯"],place:"德国柏林（国会大厦、克罗尔歌剧院）",state:"德国",sources:["1933年2月28日《关于保护人民与国家的条例》正文","1933年3月23日《消除人民与国家痛苦法》文本与表决记录"],tags:["授权法","公民权中止","一党国"]},related:["world--1933--p01"]},
{id:"world--1933--p03",track:"world",year:1933,yearApprox:false,dim:"politics",weight:3,title:"一党国确立与首批集中营",summary:"其他政党与工会相继解散，达豪营在三月末开始收押。",detail:{background:"纵火案条例与授权法之后，政权以保护人民与国家为名对反对党组织登记、查封与逮捕。",process:"1933年6至7月社民党被禁、其余政党与全国工会自行解散，7月14日颁布一党国法；3月22日达豪集中营启用。",impact:"冲锋队的街头暴力转为由党卫队管理的监禁体系，1933至1934年被拘押者以数万计（属估算）。",figures:["阿道夫·希特勒","海因里希·希姆莱","恩斯特·罗姆"],place:"德国柏林、慕尼黑附近达豪",state:"德国",sources:["1933年7月14日《党和国家统一法》文本","达豪集中营1933年早期在营名册与监管条例（达豪集中营纪念馆藏档案）"],tags:["一党国","集中营","工会解散"]},related:["world--1933--p02"]},
{id:"world--1933--p04",track:"world",year:1933,yearApprox:false,dim:"politics",weight:3,title:"日本宣布退出国联",summary:"大会通过不承认结论一个月后，东京递交退会通知。",detail:{background:"李顿报告书与1933年2月国联大会表决使日本在国际上孤立，外务省的协调路线被军部否定。",process:"1933年3月27日日本向国联递交退会通知书，松冈洋右率团在日内瓦离席；广田外相对议会以自主外交辩护。",impact:"国联失去一个常任理事国，集体安全的执行机制自此残缺，1935年对意大利的制裁更为无力。",figures:["广田弘毅","松冈洋右"],place:"瑞士日内瓦、日本东京",state:"日本／国际联盟",sources:["1933年3月27日日本致国联的退会通知书（国联文件档案）","国际联盟大会1933年2月24日表决记录"],tags:["退出国联","国际孤立","集体安全"]},related:["world--1932--p01"]},
{id:"world--1933--c01",track:"world",year:1933,yearApprox:false,dim:"culture",weight:3,title:"柏林焚书与德国学术外流",summary:"大学生在广场焚烧被指为非德意志精神的读物。",detail:{background:"德国学生联合会与宣传部门拟定作者名单，大学系统自四月起展开人事清洗。",process:"1933年5月10日在柏林及数十座大学城市举行火炬游行与焚烧；同月依《公职恢复法》解聘犹太籍与政治不可靠教师。",impact:"至1930年代中叶已有数千名学者离开德国与中欧，爱因斯坦、托马斯·曼等流亡，美国的学术与军工研究版图因此改变。",figures:["约瑟夫·戈培尔","阿尔伯特·爱因斯坦","托马斯·曼"],place:"德国柏林（歌剧院广场）",state:"德国",sources:["1933年德国学生联合会《十一条论文》与焚书行动通告","1933年4月《恢复职业公务员法》文本"],tags:["焚书","学术流亡","宣传"]},related:["world--1929--c01"]},
{id:"world--1934--p01",track:"world",year:1934,yearApprox:false,dim:"politics",weight:3,title:"长刀之夜与党军关系重整",summary:"冲锋队领导层被清除，国防军随后宣誓效忠。",detail:{background:"罗姆主张以冲锋队取代正规军骨干，1934年春与帕彭、军队和工业界的矛盾公开化。",process:"1934年6月30日至7月2日党卫队与秘密警察在柏林、巴特维塞等处决冲锋队领导人与旧敌，官方称其为镇压叛国。",impact:"清洗使国防军接受与党卫队的合流，1934年8月兴登堡死后总统与总理职权合并，军队成为政权的合伙人。",figures:["阿道夫·希特勒","恩斯特·罗姆","海因里希·希姆莱","保罗·冯·兴登堡"],place:"德国柏林、巴特维塞",state:"德国",sources:["1934年6月30日至7月2日德国政府关于镇压叛国行为的公告","1934年8月19日德国关于合并国家职权的公民投票官方文件"],tags:["清洗","冲锋队","国防军"]},related:["world--1933--p03"]},
{id:"world--1934--s01",track:"world",year:1934,yearApprox:false,dim:"science",weight:3,title:"约里奥—居里夫妇发现人工放射性",summary:"撤去放射源后铝箔仍持续放出正电子。",detail:{background:"中子的发现与轻元素的人工转变，使核反应成为可在实验室重复的过程。",process:"1934年1月他们以α源轰击铝，撤源后仍测到正电子发射与约数分钟的半衰期，并向法国《科学院院报》提交结论。",impact:"人工放射性让可测量的新核素成批出现，费米同年以中子辐照开启超铀研究，1935年诺贝尔化学奖授予约里奥—居里夫妇。",figures:["伊雷娜·约里奥—居里","弗雷德里克·约里奥—居里","恩里科·费米"],place:"法国巴黎（镭研究所）",state:"法兰西第三共和国",sources:["约里奥—居里夫妇《关于一种新的人工核放射性》（法国《科学院院报》第198卷，1934年）","费米1934年关于中子辐照感生放射性的系列论文"],tags:["人工放射性","核物理","放射化学"]},related:["world--1932--s01"]},
{id:"world--1934--i01",track:"world",year:1934,yearApprox:false,dim:"institution",weight:3,title:"苏联加入国际联盟",summary:"李维诺夫路线上位，国联获得最大的陆上成员国。",detail:{background:"德国退出国联、东方洛迦诺方案受阻后，法国与国联秘书处推动苏联入盟以补集体安全。",process:"1934年9月18日国联大会通过苏联入盟并授常任席；1935年5月《苏法互助条约》与《苏捷条约》相继签署。",impact:"集体安全在形式上补齐，但条约须经国联先行程序的保留条款，为1939年苏联重回中立路线留下伏线。",figures:["马克西姆·李维诺夫","埃里克·德拉蒙德","路易·巴尔杜"],place:"瑞士日内瓦、法国巴黎",state:"苏联／法国／国际联盟",sources:["国际联盟大会1934年9月关于苏联入盟的决议与邀请书","1935年5月2日《苏法互助条约》文本"],tags:["集体安全","国际联盟","苏法条约"]},related:["world--1933--p04"]},
{id:"world--1934--x01",track:"world",year:1934,yearApprox:false,dim:"explore",weight:3,title:"切柳斯金号沉没与空中救援",summary:"北极破冰船被浮冰压碎，陆基航空队接出冰上人员。",detail:{background:"苏联以北方海路为战略方向组织第二次大规模北极航行，船载科考与筑站人员。",process:"1934年2月13日切柳斯金号在楚科奇海被冰压碎沉没，百余人在冰上扎营；航空队在春季限期内分批接出，仅撤出时溺亡一人（据苏联官方记述）。",impact:"七名飞行员获首批苏联英雄称号，空中救援成为国家叙事的核心意象，北方海路总局随后设立。",figures:["奥托·施密特","阿纳托利·利亚皮杰夫斯基","瓦列里·契卡洛夫"],place:"楚科奇海（白令海峡以北）",state:"苏维埃社会主义共和国联盟",sources:["1934年苏联关于切柳斯金号事故与救援经过的官方报告与通报","《真理报》1934年4月关于授予首批苏联英雄称号的刊载"],tags:["北极","空中救援","科学考察"]},related:["world--1930--s01"]},
{id:"world--1935--p01",track:"world",year:1935,yearApprox:false,dim:"politics",weight:3,title:"萨尔回归与公开重整军备",summary:"公投九成回归，同月宣布恢复义务兵役并建立空军。",detail:{background:"1920年起萨尔由国联托管，凡尔赛军事条款把德国陆军限为十万并禁止拥有空军。",process:"1935年1月14日萨尔公投以约九成票回归德国；3月16日柏林宣布普遍义务兵役与空军重建，英法只提出照会抗议。",impact:"军事条款被公开撕毁而未受制裁，同年6月的英德海军协定又在事实上承认了德国的舰队扩建。",figures:["阿道夫·希特勒","约瑟夫·比尔克尔","皮埃尔·赖伐尔"],place:"德国柏林、萨尔地区",state:"德国／法国／国际联盟",sources:["1935年1月14日萨尔公投计票公告与国联萨尔治理委员会报告","1935年3月16日德国关于重建国防军与空军的政府公告"],tags:["萨尔公投","重整军备","凡尔赛条款"]},related:["world--1930--m01"]},
{id:"world--1935--p02",track:"world",year:1935,yearApprox:false,dim:"politics",weight:3,title:"《纽伦堡法》剥夺犹太人公民权",summary:"以血统与婚姻界定种族身份，帝国公民权被分级。",detail:{background:"1933至1934年各邦与部门的排斥措施与罢市已先行，党内激进派要求以统一立法收口。",process:"1935年9月15日党的全国代表会议通过《帝国公民法》与《保护德国血统与德国荣誉法》，次日由内阁以法律形式确认。",impact:"该法把排斥写成行政可执行的分类体系，1938年后的一系列补充令进一步限定职业、居所与迁移。",figures:["阿道夫·希特勒","威廉·弗里克","伯恩哈德·勒泽纳"],place:"德国纽伦堡",state:"德国",sources:["1935年9月15日《帝国公民法》与《保护德国血统与德国荣誉法》正文（帝国法律公报）","1935至1941年间《纽伦堡法》各补充令文本"],tags:["种族立法","反犹主义","公民权"]},related:["world--1933--p03"]},
{id:"world--1935--m01",track:"world",year:1935,yearApprox:false,dim:"military",weight:4,title:"意大利入侵埃塞俄比亚",summary:"自厄立特里亚与意属索马里两路进攻，次年占领首都。",detail:{background:"1934年12月瓦尔瓦尔边界冲突后，罗马以仲裁为名索要阿瓦什—奥莫走廊的处置权。",process:"1935年10月3日德·博诺与巴多利奥两路越境进攻，1936年3月起意军扩大使用毒气与空中轰炸，5月5日进入亚的斯亚贝巴。",impact:"皇帝海尔·塞拉西流亡，国联的制裁未能阻止兼并；英法的和平阵线失去信誉，罗马与柏林在1936年走近。",figures:["贝尼托·墨索里尼","埃米利奥·德·博诺","皮耶特罗·巴多利奥","海尔·塞拉西一世"],place:"埃塞俄比亚北部提格雷与欧加登",state:"意大利王国／埃塞俄比亚帝国",sources:["国际联盟大会1936年6月30日海尔·塞拉西演说的官方记录","意大利驻厄立特里亚与意属索马里司令部1935至1936年战报"],tags:["殖民战争","空中轰炸","国际联盟"]},related:["world--1926--i01"]},
{id:"world--1935--i01",track:"world",year:1935,yearApprox:false,dim:"institution",weight:3,title:"国联对意大利实施有限制裁",summary:"禁运军火与冻结贷款，却豁免石油与苏伊士运输。",detail:{background:"1935年10月7日国联行政院认定意大利构成侵略行为，盟约第十六至十九条的程序被启动。",process:"五十二国自1935年11月起执行武器禁运与金融制裁，但石油、煤炭与经苏伊士的航运获豁免；12月霍尔—赖伐尔方案被泄露后两人去职。",impact:"制裁既未阻止战争，又使埃塞俄比亚失去外援，大国此后不再把集体安全当作可信的政策变量。",figures:["塞缪尔·霍尔","皮埃尔·赖伐尔"],place:"瑞士日内瓦、法属北非",state:"国际联盟／意大利",sources:["国际联盟行政院1935年10月7日关于侵略行为的决议与制裁决定","国联制裁执行委员会1935至1936年关于豁免商品的会议记录"],tags:["集体安全","制裁失败","阿比西尼亚"]},related:["world--1935--m01"]},
{id:"world--1935--s01",track:"world",year:1935,yearApprox:false,dim:"science",weight:3,title:"汤川秀树提出核力介子理论",summary:"以交换有质量粒子解释核子间的短程强作用。",detail:{background:"原子核的结合能无法用电磁力说明，1932年海森堡的交换力方案仍缺场论表述。",process:"1935年他在《日本数理物理学会会报》发表论文，按核力作用程推得媒介粒子质量约为电子的两百倍的量级。",impact:"1937年在宇宙线中发现的穿透性粒子一度被误认为该预言的证实，1947年π介子确认后才成立，汤川获1949年诺贝尔物理学奖。",figures:["汤川秀树","维尔纳·海森堡","卡尔·安德森"],place:"日本大阪（大阪帝国大学）",state:"日本",sources:["汤川秀树《关于基本粒子的相互作用》（《日本数理物理学会会报》第三辑第17卷，1935年）","安德森与尼德迈尔1937年关于穿透性粒子的观测报告"],tags:["核力","介子理论","理论物理"]},related:["world--1932--s02"]},
{id:"world--1936--m01",track:"world",year:1936,yearApprox:false,dim:"military",weight:4,title:"德军开进莱茵非军事区",summary:"以有限兵力越过莱茵河，法英只停留在口头抗议。",detail:{background:"《凡尔赛条约》与《洛迦诺公约》规定莱茵河左岸及沿岸桥头堡永久非军事化，法德参谋部各有应对预案。",process:"1936年3月7日以数营兵力进入莱茵左岸，法国未动、英国以德国不过走进自己后院为由回避制裁。",impact:"莱茵兰的既成事实使德国得以修筑西墙并把资源投向东方，希特勒在1938年后不再担心西线的制约。",figures:["阿道夫·希特勒","路德维希·贝克","维尔纳·冯·布隆贝格"],place:"德国莱茵河左岸非军事区",state:"德国／法国",sources:["1936年3月7日德国政府照会与当日官方通讯社电讯","法国1936年3月向国联提出的声明与英国议会辩论记录"],tags:["莱茵兰","绥靖","凡尔赛体系"]},related:["world--1935--p01"]},
{id:"world--1936--e01",track:"world",year:1936,yearApprox:false,dim:"economy",weight:3,title:"凯恩斯《通论》出版",summary:"以有效需求解释失业均衡，主张以公共支出管理总量。",detail:{background:"金本位崩溃与长期大规模失业，使供给自行创造需求的传统信条难以解释现实。",process:"1936年2月麦克米伦出版《就业、利息和货币通论》，以消费倾向、资本边际效率与流动性偏好说明就业总量。",impact:"该书为赤字财政与总量管理提供理论语言，1944年布雷顿森林会议上的英国代表团方案即出其手。",figures:["约翰·梅纳德·凯恩斯","琼·罗宾逊","阿尔文·汉森"],place:"英国伦敦",state:"英国／美国",sources:["凯恩斯《就业、利息和货币通论》（1936年伦敦初版本）","1944年布雷顿森林会议英国代表团的方案与发言文件"],tags:["宏观经济学","有效需求","大萧条"]},related:["world--1930--e01"]},
{id:"world--1936--i01",track:"world",year:1936,yearApprox:false,dim:"institution",weight:3,title:"不干涉委员会与武器禁运",summary:"二十七国承诺不向西班牙输运军火，轴心国援助照常。",detail:{background:"1936年8至9月法国政府转向不干涉，英国内阁担心战争扩大并顾忌意大利在地中海的要求。",process:"1936年9月9日伦敦不干涉委员会成立，把德意日列为对象国，1937年又设边境视察与潜艇调停机构。",impact:"禁运实际只约束合法政府一侧，共和国在弹药与燃料上长期受困，不干预遂成为1938年慕尼黑的前例。",figures:["安东尼·艾登","马克西姆·李维诺夫"],place:"英国伦敦",state:"二十七缔约国／西班牙共和国",sources:["国联大会1936年9月与1937年9月关于不干涉问题的决议记录","不干涉委员会1936至1938年会议记录与英国政府公报"],tags:["不干涉","武器禁运","西班牙内战"]},related:["world--1936--m02"]},
{id:"world--1936--m02",track:"world",year:1936,yearApprox:false,dim:"military",weight:3,title:"西班牙军事叛乱与内战爆发",summary:"驻摩洛哥军团起事，政府凭民兵守住马德里。",detail:{background:"1936年2月人民阵线胜选后的土地、军队与教会改革，激化军官、地主与长枪党的对抗。",process:"7月17日摩洛哥驻军起事，佛朗哥8月抵北非接管指挥；11月政府军在马德里大学城与瓜达拉马山阻住推进。",impact:"历时近三年的内战使西班牙成为德意武器、苏联援助与国际志愿兵的共同试验场（伤亡与各派人数多属估算）。",figures:["弗朗西斯科·佛朗哥","曼努埃尔·阿萨尼亚","弗朗西斯科·拉尔戈·卡瓦列罗"],place:"西班牙马德里、布尔戈斯与西属摩洛哥",state:"西班牙共和国／反政府武装",sources:["1936年7月西班牙政府关于戒严与平叛的法令（马德里公报）","国联不干涉委员会1936年9月关于自愿人员问题的文件"],tags:["军事叛乱","内战","人民阵线"]},related:["world--1935--i01"]},
{id:"world--1936--p01",track:"world",year:1936,yearApprox:false,dim:"politics",weight:3,title:"第一次莫斯科审判",summary:"十六人被控暗杀与分裂，判决在次日执行。",detail:{background:"1934年12月基洛夫遇刺后，侦探机关把列宁格勒中心与托洛茨基相挂钩，以刑讯与家属担保取得口供。",process:"1936年8月19日至24日公开审判季诺维也夫、加米涅夫等十六人，维辛斯基主持起诉，被告当庭认罪并于判决次日被处决。",impact:"审判确立了被告自承罪状的表演式先例，1937至1938年的两次大审判与军队清洗随之展开。",figures:["格里戈里·季诺维也夫","列夫·加米涅夫","安德烈·维辛斯基","约瑟夫·斯大林"],place:"苏联莫斯科（工会大厦圆柱厅）",state:"苏维埃社会主义共和国联盟",sources:["1936年《关于反苏托洛茨基—季诺维也夫中心案件的审判材料》莫斯科官方刊本","1934年12月基洛夫案侦讯的苏联官方公报"],tags:["大清洗","莫斯科审判","政治处决"]},related:["world--1929--p02"]},
{id:"world--1937--p01",track:"world",year:1937,yearApprox:false,dim:"politics",weight:3,title:"图哈切夫斯基案与红军清洗",summary:"元帅与多名高级指挥官以间谍罪被秘密审判并处决。",detail:{background:"1936年底安全机关开始搜集针对总参谋长图哈切夫斯基的伪证，德国方面亦投放伪造材料。",process:"1937年6月11日军事最高法院特别会议闭门审判后当日执行死刑，同年秋被捕与被免职的军官数以万计（属估算）。",impact:"军官团的断层延续到1939至1940年，1941年战争初期的指挥失能与大纵深作战理论的搁置与此直接相关。",figures:["米哈伊尔·图哈切夫斯基","约瑟夫·斯大林","克利门特·伏罗希洛夫"],place:"苏联莫斯科",state:"苏维埃社会主义共和国联盟",sources:["1937年6月《真理报》关于军事法庭审判与判决执行的公开报道","1937年6月11日苏联军事最高法院特别会议判决的官方公报"],tags:["军队清洗","大清洗","苏联军事"]},related:["world--1936--p01"]},
{id:"world--1937--m01",track:"world",year:1937,yearApprox:false,dim:"military",weight:3,title:"格尔尼卡轰炸与无差别空袭",summary:"集市日的巴斯克小镇在数小时轮番攻击中起火被毁。",detail:{background:"1937年春北部战线上共和国军接连失据，德国以支援民族军为名派出空军部队参战。",process:"1937年4月26日下午起，轰炸机与战斗机对镇区轮番攻击并投掷燃烧弹；次日《泰晤士报》记者以现场报道披露城镇被毁情形。",impact:"各方对死亡人数的估计从数百到逾千不等（属估算），此役成为此后关于城市轰炸争论中最常被引用的先例。",figures:["瓦尔特·冯·里希特霍芬","乔治·斯提尔"],place:"西班牙比斯开省格尔尼卡",state:"西班牙共和国／德国干涉部队",sources:["《泰晤士报》1937年4月28日至30日格尔尼卡轰炸的现场报道","国联不干涉委员会1937年关于空袭城镇问题的会议记录"],tags:["空中轰炸","西班牙内战","无差别攻击"]},related:["world--1936--m02"]},
{id:"world--1937--c01",track:"world",year:1937,yearApprox:false,dim:"culture",weight:3,title:"毕加索完成《格尔尼卡》",summary:"为世博会西班牙馆所作的单色巨幅画成为轰炸记忆的象征。",detail:{background:"1937年1月西班牙共和国委托毕加索为世博展馆创作大幅作品，四月底的轰炸为他提供了题材。",process:"5月至6月他在巴黎完成约三点五米乘七点八米的单色巨幅画，1937年7月随西班牙馆在博览会展出。",impact:"画作此后随反战巡展流动，1939年起寄存纽约，成为二十世纪政治绘画被引用最广的图像之一。",figures:["巴勃罗·毕加索","霍安·米罗"],place:"法国巴黎（1937年世界博览会西班牙馆）",state:"法兰西第三共和国",sources:["1937年巴黎世界博览会西班牙馆展品目录与委托文件","《格尔尼卡》1939年迁运与寄存的相关馆藏记录"],tags:["绘画","反战图像","西班牙馆"]},related:["world--1937--m01"]},
{id:"world--1937--e01",track:"world",year:1937,yearApprox:false,dim:"economy",weight:3,title:"1937年苏联人口普查结果被作废",summary:"统计缺口与官方预期不符，经办者与地方官员相继获罪。",detail:{background:"1937年1月17日全苏人口普查采用新的登记办法，结果与1926年普查及官方出生率预期无法衔接。",process:"中央统计局只公布部分项目的资料册，1939年再版时删去民族与教育项，多名统计系统干部在清洗中获罪。",impact:"人口数据的缺口使饥荒与迁移的真实规模长期难以核实，1939年普查成为战前唯一可用的苏联人口基准。",figures:["约瑟夫·斯大林"],place:"苏联莫斯科",state:"苏维埃社会主义共和国联盟",sources:["1937年全苏人口普查的部分公布资料（苏联中央统计局刊行）","1939年全苏人口普查总括结果（苏联中央统计局刊行）"],tags:["人口普查","统计管制","大清洗"]},related:["world--1936--p01"]},
{id:"world--1938--p01",track:"world",year:1938,yearApprox:false,dim:"politics",weight:3,title:"德奥合并与奥地利并入帝国",summary:"在增兵压力下总理辞职，次日以法律形式宣布并入。",detail:{background:"1936年德奥协定后维也纳保持名义独立，1938年2月希特勒在贝希特斯加登召见舒施尼格逼其开放内政。",process:"3月11日赛斯—英夸特受命组阁，12日德国部队越界，13日法律宣布奥地利为帝国一省；4月公投的官方同意票逾九成九，投票在高压下进行。",impact:"一个主权国家未经战斗被并入，凡尔赛的禁止条款失去强制力，捷克斯洛伐克自此处于三面包围。",figures:["阿道夫·希特勒","库尔特·舒施尼格","阿图尔·赛斯—英夸特"],place:"奥地利维也纳、林茨",state:"德国／奥地利",sources:["1938年3月13日《奥地利重新统一于帝国的法律》文本（帝国法律公报A辑）","1938年4月10日奥地利公民投票的官方计票公告"],tags:["德奥合并","扩张","公民投票"]},related:["world--1936--m01"]},
{id:"world--1938--p02",track:"world",year:1938,yearApprox:false,dim:"politics",weight:4,title:"《慕尼黑协定》与苏台德割让",summary:"四国首脑在捷克斯洛伐克代表不在场时划定时限与边界。",detail:{background:"1938年9月苏台德德意志人党制造冲突，英国以民族自决与避免战争为由劝说布拉格让步。",process:"9月29日至30日四国在慕尼黑签署协定，规定十日期限与逐段撤离次序，英法另出保证边界剩余的声明。",impact:"捷克失去边境工事与工业区，半年后被肢解；慕尼黑成为以小国边界换取一时和平的代名词。",figures:["内维尔·张伯伦","阿道夫·希特勒","爱德华·达拉第","贝尼托·墨索里尼"],place:"德国慕尼黑",state:"德国／英国／法国／意大利",sources:["1938年9月30日四国协定正文与附件（慕尼黑协定文本）","1938年9月30日英德关于两国关系与殖民地问题的联合声明"],tags:["慕尼黑协定","割让","绥靖"]},related:["world--1936--m01"]},
{id:"world--1938--p03",track:"world",year:1938,yearApprox:false,dim:"politics",weight:3,title:"十一月反犹迫害行动",summary:"以外交官遇刺为借口的打砸与逮捕，损失被登记造册。",detail:{background:"1938年10月波兰法令使数万犹太籍居民滞留边境，11月7日一名青年在巴黎枪伤德国外交官冯·拉特。",process:"11月9日至10日冲锋队与党卫队在德国与奥地利多地袭击商店、会堂与住宅，官方当日通报死难者以十计，约三万犹太男子被送入集中营（属官方与司法调查数字）。",impact:"11月12日的会议把损失转嫁为对犹太人的赔偿税与排斥令，1941年后成为驱逐与灭绝的行政前奏。",figures:["约瑟夫·戈培尔","莱因哈德·海德里希","恩斯特·冯·拉特"],place:"德国与奥地利多地",state:"德国",sources:["1938年11月10日警察与党卫队系统的当日通报（纽伦堡审判证据文件收录）","1938年11月12日《犹太人企业排斥令》与赔偿税法令（帝国法律公报）"],tags:["反犹迫害","财产掠夺","行政命令"]},related:["world--1935--p02"]},
{id:"world--1938--s01",track:"world",year:1938,yearApprox:false,dim:"science",weight:3,title:"哈恩与施特拉斯曼证实铀核裂变",summary:"化学分析显示铀受中子辐照后出现钡，核被劈成两半。",detail:{background:"费米1934年的中子辐照研究留下超铀元素之谜，诺达克同年已提出核可能破裂的可能。",process:"1938年12月他们以化学方法排除超铀解释、检出钡，月底投稿并于1939年1月刊出；迈特纳与弗里施在流亡中给出分裂解释与能量估算。",impact:"1939年约里奥—居里与西拉德等确认裂变伴随二次中子，链式反应自此同时成为武器与反应堆的问题。",figures:["奥托·哈恩","弗里茨·施特拉斯曼","莉泽·迈特纳","奥托·弗里施"],place:"德国柏林（凯撒·威廉化学研究所）",state:"德国",sources:["哈恩与施特拉斯曼《关于铀及其他重元素受中子辐照产物的化学论证》（《自然科学》1939年第27卷）","迈特纳与弗里施《中子所致铀的分裂：一类新的核反应》（《自然》1939年第143卷）"],tags:["核裂变","放射化学","链式反应"]},related:["world--1934--s01"]},
{id:"world--1939--m01",track:"world",year:1939,yearApprox:false,dim:"military",weight:3,title:"德国吞并波希米亚与摩拉维亚",summary:"斯洛伐克宣布自治后，军队进入布拉格并设保护国。",detail:{background:"慕尼黑之后捷克斯洛伐克丧失边境地区，1939年3月斯洛伐克在德国的支持下宣告自治。",process:"3月14日至15日德军进入布拉格，15日发布关于波希米亚和摩拉维亚保护国的法令，16日设立保护长官署。",impact:"对多民族国家的公开肢解改变了英法对下一步的判断，对波兰与罗马尼亚的保证接连出台。",figures:["阿道夫·希特勒","康斯坦丁·冯·诺伊拉特"],place:"捷克斯洛伐克布拉格",state:"德国／捷克斯洛伐克",sources:["1939年3月16日关于波希米亚和摩拉维亚保护国的法令文本（帝国法律公报A辑）","1939年3月英国下院关于波兰保证的声明记录"],tags:["吞并","保护国","绥靖终结"]},related:["world--1938--p02"]},
{id:"world--1939--p01",track:"world",year:1939,yearApprox:false,dim:"politics",weight:3,title:"《苏德互不侵犯条约》与秘密议定书",summary:"十年互不侵犯之外，另有划分势力范围的附加议定书。",detail:{background:"1939年春夏英法苏军事谈判在过境权与义务范围上停滞，柏林与莫斯科转而相互试探。",process:"8月23日里宾特洛甫与莫洛托夫在莫斯科签署条约，同日签署划分波兰、波罗的海与比萨拉比亚利益的秘密附加议定书。",impact:"条约使德国得以避免两线开战，苏联取得近二十个月时间并收回1918年失去的边疆，1941年6月双方互攻。",figures:["维亚切斯拉夫·莫洛托夫","约阿希姆·冯·里宾特洛甫","约瑟夫·斯大林"],place:"苏联莫斯科",state:"苏联／德国",sources:["1939年8月23日《苏德互不侵犯条约》正文与秘密附加议定书（1948年据缴获德国外交档案刊行的文本）","1989年苏联人民代表大会关于秘密议定书法律与政治评价的决议"],tags:["互不侵犯条约","势力划分","战前外交"]},related:["world--1938--p02"]},
{id:"world--1939--m02",track:"world",year:1939,yearApprox:false,dim:"military",weight:5,title:"德国闪击波兰与二战爆发",summary:"九月一日不宣而战，三面向维斯瓦河推进，两周后苏联进兵。",detail:{background:"1939年春德国以但泽与走廊问题向波兰施压，8月25日英波同盟条约与8月23日苏德条约先后落定。",process:"9月1日晨德军自北、西、南三面进入波兰并以空军打击城市与铁路，9月8日抵华沙城外，28日华沙守军投降，10月初最后一股有组织的抵抗停止。",impact:"波兰迅速沦亡使西线进入假战争状态；占领区被分为并入区与总督府，犹太人与波兰知识分子成为首批系统性迫害对象。",figures:["格尔德·冯·伦德施泰特","费多尔·冯·博克","爱德华·雷兹—希米格维"],place:"波兰华沙、维斯瓦河与纳雷夫河沿线",state:"德国／波兰／苏联",sources:["德国1939年8月31日向波兰递交的十六点建议与9月1日开战通告","1939年9月1日希特勒关于德国空军进攻波兰的帝国议会咨文"],tags:["闪击战","二战爆发","波兰战役"]},related:["world--1939--p01"]},
{id:"world--1939--p02",track:"world",year:1939,yearApprox:false,dim:"politics",weight:3,title:"英国与法国对德宣战",summary:"保证与同盟条款被触发，西线此后九个月无大战事。",detail:{background:"1939年3月英国对波兰作出边界保证，8月25日《英波互助同盟条约》正式签署。",process:"9月3日上午英国发出最后通牒并于十一时生效，法国下午随之宣战；此后直至1940年4月西线未见大规模地面攻势。",impact:"宣战把殖民地与自治领一并带入战争，假战争时期的军备与舆论动员成为1940年失败的政治包袱。",figures:["内维尔·张伯伦","爱德华·达拉第","瓦迪斯瓦夫·西科尔斯基"],place:"英国伦敦、法国巴黎",state:"英国／法国／德国／波兰",sources:["1939年8月25日《英波互助同盟条约》文本","1939年9月3日英国下院辩论记录与对德照会"],tags:["宣战","同盟体系","假战争"]},related:["world--1939--m02"]},
{id:"world--1939--m03",track:"world",year:1939,yearApprox:false,dim:"military",weight:3,title:"苏联军队进入波兰东部",summary:"以保护同胞为名越界，与德国另订边界与友好条约。",detail:{background:"苏德秘密议定书把纳雷夫河—维斯瓦河—桑河一线以东划入苏联利益范围。",process:"9月17日红军越过边界，28日苏德签订边界与友好条约，把卢布林与东加利西亚划归德国方面，10月初在布列斯特举行联合阅兵。",impact:"11月14日当地居民被赋予苏联国籍，1940年春数十万人在四波迁移中被遣往东部与北方（属苏联内务机关统计，为估算）。",figures:["约瑟夫·斯大林","谢苗·铁木辛哥"],place:"波兰东部（利沃夫、布列斯特、维尔纽斯）",state:"苏联／德国／波兰",sources:["1939年9月17日苏联外交人民委员部致波兰大使的照会与塔斯社公告","1939年9月28日《苏德边界与友好条约》及公开议定书文本"],tags:["东方战线","边界条约","强制迁移"]},related:["world--1939--p01"]},
{id:"world--1939--s01",track:"world",year:1939,yearApprox:false,dim:"science",weight:3,title:"裂变二次中子与致罗斯福的信",summary:"八月一封署名爱因斯坦的长信把链式反应送上白宫议程。",detail:{background:"1939年1至3月各实验室确认铀裂变并测得二次中子，华盛顿开始管制铀与石墨的出口。",process:"8月2日爱因斯坦致罗斯福的信由萨克斯于10月11日送达，同日西拉德与维格纳当面陈说，10月21日铀顾问委员会成立。",impact:"从实验室到国家项目的转换由此开始，1941年穆德委员会与1942年曼哈顿计划循此路径展开。",figures:["利奥·西拉德","阿尔伯特·爱因斯坦","亚历山大·萨克斯","恩里科·费米"],place:"美国华盛顿、纽约",state:"美国",sources:["1939年8月2日爱因斯坦致罗斯福信（富兰克林·罗斯福图书馆藏原件）","1939年10月21日罗斯福关于设立铀顾问委员会的白宫备忘录"],tags:["链式反应","核研究","战时科学"]},related:["world--1938--s01"]},
{id:"world--1940--m01",track:"world",year:1940,yearApprox:false,dim:"military",weight:4,title:"西线闪击与法国沦陷",summary:"五日渡过色当，二十六天内把英法联军推到海峡沿岸。",detail:{background:"1940年春法军主力置于比利时方向，德军把主攻改向阿登，马奇诺防线只覆盖法德边界。",process:"5月10日德军同时进入荷兰与比利时，14日在色当强渡马斯河，20日抵阿布维尔切断北路联军退路。",impact:"敦刻尔克撤出约三十三万人（据英国官方通报），6月22日停战使德国取得大西洋沿岸基地，战争转入不列颠之战。",figures:["海因茨·古德里安","马克西姆·魏刚","约翰·戈特"],place:"法国色当、阿布维尔与敦刻尔克",state:"德国／法国／英国／比利时／荷兰",sources:["英国陆军部1940年发电机行动通报与戈特勋爵的作战报告","法国陆军部战史处1940年东北方面军作战日志与每日通报"],tags:["闪击战","法国战役","敦刻尔克"]},related:["world--1939--m02"]},
{id:"world--1940--m02",track:"world",year:1940,yearApprox:false,dim:"military",weight:3,title:"不列颠之战与防空体系的考验",summary:"以机场与雷达站为重点的空袭未能取得制空权。",detail:{background:"1940年夏德国以潜艇与空军封锁英伦三岛，英国战斗机司令部以有限兵力防守东南沿海。",process:"8月中旬起德军集中打击海峡船队、港口与雷达站，9月7日后转为夜袭伦敦，10月12日海狮计划被推迟。",impact:"链状雷达网、统一指挥与飞机补充使德军未能夺取制空权，1941年春其航空兵力转往巴尔干与东线。",figures:["休·道丁","基思·帕克","赫尔曼·戈林"],place:"英国英格兰东南部与伦敦",state:"英国／德国",sources:["英国空军部1940年战斗机司令部作战记录与道丁的事后陈述","1940年8至10月德国空军第2、第3航空队作战日志"],tags:["空战","雷达","制空权"]},related:["world--1940--m01"]},
{id:"world--1940--p01",track:"world",year:1940,yearApprox:false,dim:"politics",weight:3,title:"贡比涅停战与维希政权成立",summary:"六月二十二日同德国签约，七月十日授全权给贝当。",detail:{background:"6月16日雷诺去职、贝当继任后，内阁多数主张先求停战以保存舰队、殖民地与行政体系。",process:"6月22日与德国在贡比涅同一节车厢签字，24日与意大利签约；7月10日国民议会把制宪权交给贝当，政府移驻维希。",impact:"停战条款使法国承担占领费并交出舰队，1940至1944年的立法与行政在战后成为审判与政治清算的对象。",figures:["菲利普·贝当","保罗·雷诺","夏尔·戴高乐"],place:"法国贡比涅、维希",state:"法国（维希政权）／德国",sources:["1940年6月22日法德停战协定正文与附加议定书","1940年7月10日国民议会授予贝当全权的宪法性法律文本"],tags:["停战","维希法国","占领"]},related:["world--1918--p03"]},
{id:"world--1940--f01",track:"world",year:1940,yearApprox:false,dim:"figure",weight:3,title:"戴高乐的六月十八日号召",summary:"在伦敦经广播呼吁继续抗战，并否认停战的合法性。",detail:{background:"6月16日内阁改组后，与英国的合并方案在波尔多受阻，部分军政与殖民地长官态度未定。",process:"6月18日下午他在伦敦通过英国广播公司宣读简短文稿，英国政府于28日承认其为自由法国人的领袖。",impact:"号召在军事上几乎无即时效应，却把流亡机构与殖民地资源留在盟国一侧，成为战后法国的合法性论据。",figures:["夏尔·戴高乐","温斯顿·丘吉尔"],place:"英国伦敦（英国广播公司播音室）",state:"自由法国／英国",sources:["1940年6月18日戴高乐广播文稿（收入其《战争回忆录》第一卷）","1940年6月28日英国政府承认戴高乐的官方声明"],tags:["自由法国","广播","流亡政权"]},related:["world--1940--p01"]},
{id:"world--1940--p02",track:"world",year:1940,yearApprox:false,dim:"politics",weight:3,title:"卡廷等处决被俘波兰人员",summary:"内务机关在1940年春处决战俘与羁押人员两万一千余人。",detail:{background:"1939年秋苏联在波兰东部收容约两万名军人、警官与知识分子，分置于卡廷、斯塔罗别利斯克与科泽利斯克三处营区。",process:"1940年3月5日贝利亚提出处决建议并附名单，四五月间在卡廷森林、哈尔科夫与加里宁等地执行；1943年4月德国公布墓地发现。",impact:"处决数字以1940年3月案卷所载两万一千七百六十八人为据，苏联与波兰流亡政府就责任归属争执延续至1990年。",figures:["拉夫连季·贝利亚","约瑟夫·斯大林","瓦迪斯瓦夫·西科尔斯基"],place:"苏联卡廷森林、哈尔科夫、加里宁",state:"苏联／波兰",sources:["1940年3月5日贝利亚的处决建议与执行名单（1990年代莫斯科公布的《特殊档案袋第1号》文件集）","1990年苏联塔斯社关于卡廷事件责任认定的声明"],tags:["战俘处决","卡廷","苏波关系"]},related:["world--1939--m03"]},
{id:"world--1941--m01",track:"world",year:1941,yearApprox:false,dim:"military",weight:5,title:"巴巴罗萨行动与苏德战争爆发",summary:"六月二十二日三路突进，数月内连续完成大合围。",detail:{background:"1940年11月莫洛托夫访柏林后谈判无果，12月18日的作战指令把进攻准备指向东线。",process:"6月22日凌晨德军与盟国部队自波罗的海至喀尔巴阡发动进攻，9月中旬完成基辅合围，10月初在维亚济马与布良斯克再度合围。",impact:"苏联1941年的人员损失以百万计（属双方战史估算），但莫斯科、列宁格勒与斯大林格勒未陷，战争转为长期消耗。",figures:["阿道夫·希特勒","格奥尔吉·朱可夫","海因茨·古德里安","谢苗·铁木辛哥"],place:"苏联西部（布列斯特、明斯克、基辅、斯摩棱斯克）",state:"德国及其盟国／苏联",sources:["1940年12月18日德国第21号指令关于对苏作战准备的文本","苏联国防部档案馆藏1941年西部特别军区作战文书与损失报告"],tags:["苏德战争","合围战","东线"]},related:["world--1939--p01"]},
{id:"world--1941--m02",track:"world",year:1941,yearApprox:false,dim:"military",weight:3,title:"莫斯科会战与十二月反攻",summary:"十月攻势在城郊耗尽，十二月五日红军转入反攻。",detail:{background:"9月底台风行动开始，德军补给线拉长、秋雨使道路失能，苏军自远东与西伯利亚陆续西调。",process:"10至11月德军推进至克林、亚赫罗马与图拉一线，12月5日前后三个方面军在空军支援下转入反攻。",impact:"莫斯科未陷使德国的速决方案失效，12月8日希特勒自任陆军总司令并禁止后撤，东线进入第二年战争。",figures:["格奥尔吉·朱可夫","费多尔·冯·博克","海因茨·古德里安","约瑟夫·斯大林"],place:"苏联莫斯科西北与南郊（克林、图拉）",state:"苏联／德国",sources:["德国中央集团军群1941年10至12月作战日志（战后出版的东线文件）","苏联西方面军1941年12月反攻命令与作战通报"],tags:["莫斯科","冬季反攻","东线"]},related:["world--1941--m01"]},
{id:"world--1941--p01",track:"world",year:1941,yearApprox:false,dim:"politics",weight:4,title:"《大西洋宪章》与战后目标",summary:"八条原则写进战时目标，含自决、贸易与公海自由。",detail:{background:"1941年8月美英参谋长在大西洋北部会合前先举行预备会议，两国首脑在纽芬兰附近会合。",process:"8月14日公布联合文件，主张不谋求领土扩张、尊重人民选择政府形式、削减关税与共享海洋。",impact:"宪章成为1942年《联合国家宣言》与1945年《联合国宪章》的前导文本，其自决条款也被殖民地的政治力量引用。",figures:["温斯顿·丘吉尔","富兰克林·罗斯福"],place:"北大西洋纽芬兰附近（威尔士亲王号与奥古斯塔号）",state:"英国／美国",sources:["1941年8月14日英美联合宣言正文（大西洋宪章）","1941年1月至8月美英参谋长ABC—1会议议定文件"],tags:["战时目标","民族自决","美英同盟"]},related:["world--1940--f01"]},
{id:"world--1941--p02",track:"world",year:1941,yearApprox:false,dim:"politics",weight:3,title:"《租借法》实施与盟国物资动员",summary:"以非现金方式供应军火与粮食，先及英国后及苏联。",detail:{background:"1940年末英国的现金支付与现购自运能力接近耗尽，美国国内关于中立法与援英的争论持续。",process:"1941年3月11日签署租借法，同年秋起经北极船队向苏联运货，至战争结束对三十余个国家的供应总额以百亿美元计（属美国官方清算统计）。",impact:"租借法使美国成为盟国的兵工厂并建立战时生产管理体制，战后清算与对苏援助规模成为外交争议。",figures:["富兰克林·罗斯福","爱德华·斯退提纽斯","温斯顿·丘吉尔"],place:"美国华盛顿",state:"美国／英国／苏联",sources:["1941年3月11日美国《租借法》正文","美国对外经济管理局1945年关于租借供应与清算的统计报告"],tags:["租借法","战时经济","盟国供应"]},related:["world--1941--m01"]},
{id:"world--1941--m03",track:"world",year:1941,yearApprox:false,dim:"military",weight:4,title:"珍珠港袭击与太平洋战争爆发",summary:"十二月七日晨袭击夏威夷基地，同日进攻马来亚与菲律宾。",detail:{background:"1940年9月三国同盟与1941年7月进驻法属印度支那后，美国冻结日本资产并实行石油禁运。",process:"12月7日晨舰载机分两波攻击珍珠港与瓦胡岛机场，同日日本对美英开战，马来亚与菲律宾同时受袭。",impact:"12月8日美国对日宣战、11日德国对美宣战，美国的工业与人力资源自此全面投入同盟国一方。",figures:["富兰克林·罗斯福","山本五十六","温斯顿·丘吉尔"],place:"美国夏威夷瓦胡岛珍珠港",state:"日本／美国／英国",sources:["1941年12月8日罗斯福在国会两院联席会议的宣战咨文","美国1941至1946年关于珍珠港事件的罗伯茨委员会与联合委员会记录"],tags:["珍珠港","太平洋战争","宣战"]},related:["world--1941--p01", "cn--1941--p02"]},
{id:"world--1942--p01",track:"world",year:1942,yearApprox:false,dim:"politics",weight:4,title:"万湖会议与驱逐的行政协调",summary:"十二个部门开会协调对欧洲犹太人的驱逐与处置。",detail:{background:"1941年夏起东方占领区出现大规模枪杀行动，1941年秋柏林开始限制犹太人迁出并组织遣送。",process:"1942年1月20日党卫队与政府各部门在柏林郊外万湖旁开会，海德里希主持，记录使用最终解决与欧洲犹太人等措辞。",impact:"1942年3月起索比堡、贝乌热特与特雷布林卡等灭绝营投入运转，1942至1944年被遣送与遇害规模由战后各国调查逐步确定（属估算）。",figures:["莱因哈德·海德里希","阿道夫·艾希曼"],place:"德国柏林万湖",state:"德国",sources:["1942年1月20日万湖会议记录抄件与与会名单（纽伦堡后续审判证据文件）","1933至1941年关于犹太人登记、迁移与财产没收的帝国法律公报文本"],tags:["大屠杀","行政协调","驱逐"]},related:["world--1938--p03"]},
{id:"world--1942--p02",track:"world",year:1942,yearApprox:false,dim:"politics",weight:3,title:"《联合国家宣言》二十六国签字",summary:"确认《大西洋宪章》纲领并对轴心国作战到底。",detail:{background:"1941年8月美英联合宣言后，苏联与各国流亡运动代表相继表示接受其原则。",process:"1942年1月1日美英苏中四国首先在华盛顿签字，其后二十一个国家陆续加入；宣言未经各国议会批准，也无执行机构。",impact:"联合国作为同盟国的名称由此固定，1944年敦巴顿橡树园会议与1945年旧金山制宪会议均援引其文本。",figures:["富兰克林·罗斯福","温斯顿·丘吉尔","马克西姆·李维诺夫","宋子文"],place:"美国华盛顿",state:"美国／英国／苏联／中国等二十六国",sources:["1942年1月1日《联合国家宣言》正文与各国签字页（美国国务院刊本）","1945年《联合国宪章》关于本宣言的援引文本"],tags:["同盟国","宣言","联合国前身"]},related:["world--1941--p01"]},
{id:"world--1942--m01",track:"world",year:1942,yearApprox:false,dim:"military",weight:3,title:"中途岛海战与日本攻势止步",summary:"三日内损失四艘舰队航母，占领中途岛的计划取消。",detail:{background:"1942年春日本以占领中途岛为饵企图诱歼美舰队主力，其作战密码已被美军部分破译。",process:"6月4日至7日机动部队在美舰载机攻击中损失四艘舰队航母及大量舰载机与地勤人员，山本决定西撤。",impact:"航母与合格飞行员的补充再未跟上，1942年8月瓜达尔卡纳尔之战后日本长期处于守势。",figures:["切斯特·尼米兹","雷蒙德·斯普鲁恩斯","南云忠一"],place:"太平洋中途岛以北海域",state:"美国／日本",sources:["美国太平洋舰队1942年6月中途岛作战报告与夏威夷情报站破译记录","日本军令部1942年MI作战与AL作战经过记录"],tags:["航母海战","中途岛","情报破译"]},related:["world--1941--m03"]},
{id:"world--1942--m02",track:"world",year:1942,yearApprox:false,dim:"military",weight:3,title:"阿拉曼战役与北非攻势易手",summary:"十月的突破与追击把德意军队逐回昔兰尼加。",detail:{background:"1942年6月托卜鲁克陷落后，德意军队推进至阿拉曼，埃及与苏伊士运河直接受威胁。",process:"10月23日夜英军以火力准备发动进攻，11月2日完成突破并转入追击，11月8日美英同时在法属北非登陆。",impact:"轴心国在北非失去战略主动权，1943年5月突尼斯的二十余万守军投降（属英方战史统计）。",figures:["伯纳德·蒙哥马利","埃尔温·隆美尔"],place:"埃及阿拉曼、托卜鲁克",state:"英国／德国与意大利／自由法国",sources:["英国陆军部中东战场官方战史与1942年阿拉曼作战报告","隆美尔1941至1944年战役日记与命令文件（战后整理出版本）"],tags:["北非战场","阿拉曼","两栖登陆"]},related:["world--1942--m01"]},
{id:"world--1942--m03",track:"world",year:1942,yearApprox:false,dim:"military",weight:4,title:"斯大林格勒战役与第6集团军被围",summary:"九月起逐街争夺，十一月合围，次年二月投降。",detail:{background:"1942年夏德军主攻转向高加索油田与伏尔加河，城市同时是工业目标与象征目标。",process:"8月下旬德军突入城区，9至11月在马马耶夫岗与拖拉机厂反复争夺；11月19日至23日天王星行动完成合围，围内约二十余万至三十万人（属估算）。",impact:"1943年2月2日被围部队投降，德军及其盟国损失以十万计，东线战略主动权转至苏联一侧。",figures:["瓦西里·崔可夫","格奥尔吉·朱可夫","弗里德里希·保卢斯","约瑟夫·斯大林"],place:"苏联斯大林格勒（今伏尔加格勒）",state:"苏联／德国及其盟国",sources:["苏联62集团军与斯大林格勒方面军1942年9月至1943年2月作战通报","德国第6集团军被围期间的通信记录与日记抄件（战后出版文件）"],tags:["围城战","斯大林格勒","东线"]},related:["world--1941--m02"]},
{id:"world--1942--s01",track:"world",year:1942,yearApprox:false,dim:"science",weight:3,title:"芝加哥1号堆实现可控链式反应",summary:"十一月二日石墨铀堆自持运行约半小时。",detail:{background:"1941年12月罗斯福批准研制原子弹，1942年8月陆军工程兵团接管研究并成立曼哈顿计划。",process:"1942年12月2日下午在芝加哥大学斯塔格球场看台下，费米下令逐级抽出控制棒，堆体自持运行约二十八分钟。",impact:"临界实验证明钚可在反应堆中生产，橡树岭与汉福德的工厂随之扩建，核能从此进入工程阶段。",figures:["恩里科·费米","利奥·西拉德","阿瑟·康普顿"],place:"美国芝加哥大学（斯塔格球场看台）",state:"美国",sources:["芝加哥大学冶金实验室1942至1943年关于反应堆的技术报告（CP—1文件系列）","斯迈思《核能用于军事目的》（1945年公开本）"],tags:["核反应堆","链式反应","曼哈顿计划"]},related:["world--1939--s01"]},
{id:"world--1942--p03",track:"world",year:1942,yearApprox:false,dim:"politics",weight:3,title:"《贝弗里奇报告》设计战后社会保障",summary:"以贫困、疾病等五大问题为对象，提出普遍性社会保险。",detail:{background:"战时联合政府需要一项共同的社会目标，劳工与国民服务部的跨部门协调为改革铺路。",process:"1942年11月《社会保险与相关服务》提出统一缴费与统一给付、家庭补助与国民救助三项原则，小册子迅速畅销。",impact:"报告成为1945至1948年英国社会立法蓝本，国民保险法与国民保健服务法先后把它付诸实施。",figures:["威廉·贝弗里奇","欧内斯特·贝文","克莱门特·艾德礼"],place:"英国伦敦",state:"英国",sources:["《社会保险与相关服务》（英国皇家命令文书第6404号，1942年11月）正文","1945至1948年英国国民保险法与国民保健服务法文本"],tags:["社会保障","福利国家","战时规划"]},related:["world--1931--e02"]},
{id:"world--1943--m01",track:"world",year:1943,yearApprox:false,dim:"military",weight:3,title:"库尔斯克会战与奥廖尔突出部",summary:"七月的攻防与坦克交战耗尽德军东线预备队。",detail:{background:"斯大林格勒之后，德军打算在库尔斯克突出部实施一次钳形反击，苏军事先得知进攻企图并构筑多层防御。",process:"7月5日起德军自南北两面突入，12日普罗霍罗夫卡一带发生坦克交战，苏军的库图佐夫与鲁缅采夫行动相继展开。",impact:"德军再未能在东线发动战略性夏季攻势，8月5日奥廖尔与别尔哥罗德收复，苏军转入连续的外线进攻。",figures:["格奥尔吉·朱可夫","康斯坦丁·罗科索夫斯基","埃里希·冯·曼施坦因"],place:"苏联库尔斯克以北以南与奥廖尔、别尔哥罗德",state:"苏联／德国",sources:["苏联中央方面军与沃罗涅日方面军1943年7月作战通报","德国第9集团军与第4装甲集团军1943年7月作战日志"],tags:["库尔斯克","坦克战","东线"]},related:["world--1942--m03"]},
{id:"world--1943--m02",track:"world",year:1943,yearApprox:false,dim:"military",weight:3,title:"西西里登陆与墨索里尼倒台",summary:"攻入意大利本土后，大法西斯会议罢免并拘捕领袖。",detail:{background:"1943年1月卡萨布兰卡会议把下一目标定为地中海，5月突尼斯战事结束后盟军着手登陆准备。",process:"7月10日美英加与自由法国部队在西西里东南部上岸，8月17日战役结束，德意部队撤走约十万人（属英方战史估算）；7月25日巴多格里奥接任组阁。",impact:"意大利转入停战谈判并于9月8日宣布停战，德国随即解除意军武装并控制罗马以北，半岛成为长期战场。",figures:["德怀特·艾森豪威尔","彼得罗·巴多格里奥","贝尼托·墨索里尼"],place:"意大利西西里岛与撒丁、那不勒斯",state:"盟国／意大利／德国",sources:["盟军第15集团军群1943年哈斯基行动作战报告","1943年7月25日大法西斯会议决议与意大利王室关于拘捕墨索里尼的公告"],tags:["西西里","政权更迭","停战"]},related:["world--1942--m02"]},
{id:"world--1943--d01",track:"world",year:1943,yearApprox:false,dim:"disaster",weight:3,title:"1943年孟加拉饥荒",summary:"稻收病害与粮价暴涨之下，数百万人死于饥饿与疫病。",detail:{background:"1942年缅甸稻米进口中断、军需采购与拒收政策推高粮价，同年10月的气象灾害与霍乱加重灾情。",process:"1943年3至12月达卡与吉大港等地出现大规模饥饿死亡，省政府的以工代赈与粮食调运在年中才展开。",impact:"据官方调查与后续研究估计，1943至1944年的死亡在二百万至三百万人之间（属估算），饥荒成为殖民责任争论的焦点。",figures:["维克多·韦维尔","温斯顿·丘吉尔"],place:"英属印度孟加拉省（达卡、吉大港）",state:"英属印度",sources:["《孟加拉饥荒调查委员会报告》（1945年刊本）","1943年印度供应部与帝国内阁关于粮食调运的往来文件"],tags:["饥荒","粮食供给","殖民统治"]},related:["world--1930--p01"]},
{id:"world--1943--p01",track:"world",year:1943,yearApprox:false,dim:"politics",weight:4,title:"德黑兰会议与第二战场的定期",summary:"三巨头确认1944年横渡海峡，并就波兰边界展开争执。",detail:{background:"1943年10月莫斯科外长会议与开罗会谈之后，斯大林坚持在欧洲西北部开辟第二战场。",process:"11月28日至12月1日在德黑兰举行三次全会，通过三边《宣言》并确定霸王行动的时限，同时非正式讨论波兰东西边界。",impact:"第二战场的时间被固定，苏联对日作战的口头承诺与波兰边界问题一同进入战后安排的争议。",figures:["约瑟夫·斯大林","富兰克林·罗斯福","温斯顿·丘吉尔"],place:"伊朗德黑兰（苏联公使馆）",state:"苏联／美国／英国／伊朗",sources:["1943年12月1日德黑兰三边宣言正文与军事会谈纪要","《美国对外关系文件：德黑兰会议卷》所收会议记录"],tags:["三巨头","第二战场","战后安排"]},related:["world--1942--p02"]},
{id:"world--1943--s01",track:"world",year:1943,yearApprox:false,dim:"science",weight:3,title:"科洛瑟斯破译机在布莱切利园启用",summary:"以真空管设备高速比对电传密码的候选密钥。",detail:{background:"1940年起布莱切利园以机电检验机破解恩尼格马，1941年发现洛伦兹电传密码构成的新威胁。",process:"1943年12月首台科洛瑟斯在8号棚安装，以一千五百余只真空管比对密钥纸带，1944年2月起参与西北欧战报的破译。",impact:"战争结束前共有十台同类机器运转，密码分析从人工语言工作转向电子设备，战后英国计算机研究由此承接人才与机型。",figures:["马克斯·纽曼","汤米·弗劳尔斯","阿兰·图灵"],place:"英国布莱切利园",state:"英国",sources:["1943至1945年布莱切利园关于洛伦兹密码破译的技术报告（2000年公开的档案文件）","英国国家档案馆关于科洛瑟斯机重建与解密的公开卷宗"],tags:["密码破译","早期计算机","战时科学"]},related:["world--1942--m01"]},
{id:"world--1944--m01",track:"world",year:1944,yearApprox:false,dim:"military",weight:4,title:"诺曼底登陆与西线第二战场",summary:"六月六日五处海滩抢滩，两个月后盟军抵莱茵河。",detail:{background:"德黑兰会议把霸王行动定于1944年5月，因意大利战事与登陆艇不足推迟到6月。",process:"6月6日凌晨空降部队深入敌后、晨间在五个海滩抢滩，7月25日眼镜蛇行动完成突破，8月25日进入巴黎。",impact:"德国被迫在两线进行消耗战，1944年秋的补给危机与市场花园行动失败使其失去主动，1945年3月盟军渡过莱茵河。",figures:["德怀特·艾森豪威尔","伯纳德·蒙哥马利","奥马尔·布拉德利","格尔德·冯·伦德施泰特"],place:"法国诺曼底（卡朗坦、圣洛、卡昂）",state:"盟国／德国／法国",sources:["盟国远征军最高司令部1944年霸王行动作战计划与战后官方战史","1944年6月6日艾森豪威尔致部队的登陆令与6月7日战况通报"],tags:["两栖登陆","第二战场","西线"]},related:["world--1943--p01"]},
{id:"world--1944--m02",track:"world",year:1944,yearApprox:false,dim:"military",weight:3,title:"巴格拉基昂行动与白俄罗斯解放",summary:"六月二十二日的突击使德军中央集团军群崩溃。",detail:{background:"苏军以欺骗措施把德军判断引向乌克兰方向，四个方面军把兵力集中于维捷布斯克至博布鲁伊斯克正面。",process:"6月22日至29日两面突破并完成两次合围，7月3日收复明斯克，8月下旬抵华沙东郊与东普鲁士边界。",impact:"德国中央集团军群损失二十余万至二十五万人（属西方战史估算），苏军快速推进中补给线拉长的局限同时暴露。",figures:["康斯坦丁·罗科索夫斯基","伊万·科涅夫","格奥尔吉·朱可夫"],place:"白俄罗斯维捷布斯克、博布鲁伊斯克与明斯克",state:"苏联／德国",sources:["苏联白俄罗斯第1、第2方面军1944年6至8月作战通报","德国中央集团军群1944年6至8月的部署与损失记录"],tags:["合围战","白俄罗斯","东线"]},related:["world--1944--m01"]},
{id:"world--1944--m03",track:"world",year:1944,yearApprox:false,dim:"military",weight:3,title:"华沙起义与首都的毁灭",summary:"起义坚持六十三天，德军以报复与逐街摧毁回应。",detail:{background:"1944年7月苏军抵维斯瓦河东岸，波兰地下政府与本土军指挥层决定在苏军进入前夺回首都。",process:"8月1日清晨本土军在城内发动，9月起苏军停止推进而盟军远程补给有限，10月2日起义方签订投降条件。",impact:"起义军人死亡与平民死难以万计（属波兰与德方战后调查估算），老城被系统炸毁，战后波兰权力结构在1945年确定。",figures:["塔德乌什·博尔—科莫罗夫斯基","斯坦尼斯瓦夫·米科瓦伊奇克"],place:"波兰华沙",state:"波兰地下国／德国／苏联",sources:["1944年8至10月德方华沙行动的每日报告（党卫队与警察系统文件）","1944年10月2日起义军投降条件文本与波兰伦敦政府档案"],tags:["城市起义","平民报复","战后波兰"]},related:["world--1944--m02"]},
{id:"world--1944--p01",track:"world",year:1944,yearApprox:false,dim:"politics",weight:4,title:"布雷顿森林会议与国际货币秩序",summary:"四十四国确立可调整盯住汇率与两个国际基金组织。",detail:{background:"1941至1943年美英就战后清算与稳定方案反复磋商，凯恩斯与怀特各提出自己的国际清算设计。",process:"1944年7月1日至22日在新罕布什尔州开会，通过国际货币基金组织与国际复兴开发银行条款，以黄金平价作为汇率基础。",impact:"美元成为战后货币体系的轴心，1947年的关税与贸易总协定与其并行，可调整盯住安排维持到1971年之后解体。",figures:["约翰·凯恩斯","哈里·德克斯特·怀特","亨利·摩根索"],place:"美国新罕布什尔州布雷顿森林",state:"四十四国与会方",sources:["1944年7月22日会议最后文件：《国际货币基金组织条款》与《国际复兴开发银行协定》","1943年4月美国稳定基金方案与英国清算同盟方案文本"],tags:["国际货币","美元","战后经济秩序"]},related:["world--1930--e01"]},
{id:"world--1944--p02",track:"world",year:1944,yearApprox:false,dim:"politics",weight:3,title:"巴黎解放与共和国临时政府",summary:"八月二十五日德军投降，戴高乐入城重建共和权威。",detail:{background:"诺曼底登陆后，国内抵抗力量与法兰西民族解放委员会争夺对行政与武装的控制权。",process:"8月19日起城内武装起义，24至25日勒克莱尔的第二装甲师入城并接受德军投降，9月临时政府在巴黎行使职权。",impact:"解放委员会与司法清洗同步展开，1945至1946年的选举与制宪把抵抗运动的合法性转化为制度安排。",figures:["夏尔·戴高乐","菲利普·勒克莱尔","迪特里希·冯·沙尔蒂茨"],place:"法国巴黎",state:"法国（临时政府）／德国",sources:["1944年8月25日巴黎德军投降文本与盟军司令部公告","戴高乐1944年8至9月在巴黎的演说与政府公报（《战争回忆录》解放卷）"],tags:["解放","政权重建","政治清洗"]},related:["world--1940--f01"]},
{id:"world--1945--p01",track:"world",year:1945,yearApprox:false,dim:"politics",weight:4,title:"雅尔塔会议与战后欧洲的划界",summary:"二月首脑会谈确定德国分区占领与联合国表决程序。",detail:{background:"1945年2月苏军已抵奥得河，英美希望苏联尽早对日作战并参与德国的处置。",process:"2月4日至11日在克里米亚举行三次全会，通过德国分区占领与非军事化决议，并就波兰边界与政府改组达成协议。",impact:"联合国的表决程序在会内定案，远东秘密协定则把外蒙古与满洲权益交予苏联；1945年后的欧洲分裂格局自此成形。",figures:["富兰克林·罗斯福","温斯顿·丘吉尔","约瑟夫·斯大林"],place:"苏联克里米亚雅尔塔（利瓦季亚宫）",state:"美国／英国／苏联",sources:["1945年2月11日雅尔塔会议议定书与《被解放欧洲的宣言》正文","1945年2月11日关于苏联对日作战的秘密协定文本（后由美国国务院公开）"],tags:["三巨头","分区占领","联合国表决"]},related:["world--1943--p01"]},
{id:"world--1945--d01",track:"world",year:1945,yearApprox:false,dim:"disaster",weight:3,title:"德累斯顿与东京的大规模空袭",summary:"二月与三月的两次燃烧弹轰炸各造成数万至十万量级死难。",detail:{background:"1944年末起美英空军对德国城市与日本工业区实施昼夜连续轰炸，燃烧弹与夜间编队成为主要手段。",process:"1945年2月13至15日英美空军三度袭击德累斯顿，3月9至10日美军以重型轰炸机对东京下町实施燃烧弹轰炸并引发大火。",impact:"据2010年德国官方历史委员会研究与美方调查统计，两次空袭的死难各以数万人计（属估算），其军事必要与法律边界至今是战争史的争论题目。",figures:["阿瑟·哈里斯","卡尔·斯帕茨"],place:"德国德累斯顿、日本东京",state:"英国／美国／德国／日本",sources:["德累斯顿市历史委员会2010年报告《1945年2月对德累斯顿的空袭与死难人数》","美国战略轰炸调查团1945年对日轰炸效果报告与东京消防厅记录"],tags:["战略轰炸","燃烧弹","城市破坏"]},related:["world--1937--m01"]},
{id:"world--1945--m01",track:"world",year:1945,yearApprox:false,dim:"military",weight:3,title:"柏林战役与希特勒之死",summary:"四月十六日突破奥得河，二十五日合围，五月二日投降。",detail:{background:"雅尔塔之后苏军完成维斯瓦河—奥得河战役，以优势兵力与两个方面军指向首都。",process:"4月16日苏军突破泽劳高地，25日完成对柏林的合围并攻入城区；30日希特勒自杀，5月2日柏林卫戍部队投降。",impact:"德军在5月8日前分段向苏美英投降，城市争夺战的损失与占领初期针对平民的暴力，成为战后德国与波兰记忆政治的争点。",figures:["格奥尔吉·朱可夫","伊万·科涅夫","阿道夫·希特勒","瓦西里·崔可夫"],place:"德国柏林与奥得河—施普雷河一线",state:"苏联／德国",sources:["苏联白俄罗斯第1方面军与乌克兰第1方面军1945年4至5月作战通报","德国陆军总参谋部与柏林卫戍部队1945年4月下旬通信记录（战后出版文件）"],tags:["柏林战役","政权终结","东线"]},related:["world--1944--m02"]},
{id:"world--1945--p02",track:"world",year:1945,yearApprox:false,dim:"politics",weight:5,title:"德国无条件投降与欧洲战事结束",summary:"五月八日深夜生效的投降文书结束德国的战争。",detail:{background:"5月2日柏林投降后，邓尼茨政府试图让西线部队向英美单独投降，艾森豪威尔拒绝部分投降。",process:"5月7日在兰斯签署全体武装力量的投降文书，8日深夜在柏林再签并经三边与法国批准，5月8日23时01分生效。",impact:"欧洲战事结束，德国被置于四国占领与纽伦堡审判的管辖之下，东部边界与数百万德意志族居民的迁移问题留待波茨坦处理。",figures:["威廉·凯特尔","德怀特·艾森豪威尔","格奥尔吉·朱可夫","卡尔·邓尼茨"],place:"法国兰斯、德国柏林卡尔斯霍斯特",state:"德国／苏联／美国／英国／法国",sources:["1945年5月7日兰斯投降文书与5月8日柏林再签文本（三边公布的正式文本）","1945年6月5日四国关于德国失败的柏林宣言正文"],tags:["无条件投降","停战","四国占领"]},related:["world--1945--m01"]},
{id:"world--1945--p03",track:"world",year:1945,yearApprox:false,dim:"politics",weight:4,title:"《联合国宪章》签署与组织成立",summary:"五十国代表在旧金山制宪，宪章十月二十四日生效。",detail:{background:"1944年敦巴顿橡树园会议已拟出组织草案，雅尔塔会议确定表决程序并召集制宪会议。",process:"1945年4月25日至6月26日五十国代表在旧金山开会并通过宪章，波兰被补列入创始会员国，10月24日宪章生效。",impact:"新组织取得对和平与侵略的裁断权并设国际法院，国联的资产与职能在1946年移交，托管制度取代了委任统治。",figures:["爱德华·斯退提纽斯","安东尼·艾登","维亚切斯拉夫·莫洛托夫","顾维钧"],place:"美国旧金山",state:"五十个创始会员国",sources:["1945年6月26日《联合国宪章》正文与《国际法院规约》","1944年敦巴顿橡树园会议四大国建议案文本"],tags:["国际组织","安理会","集体安全"]},related:["world--1942--p02"]},
{id:"world--1945--p04",track:"world",year:1945,yearApprox:false,dim:"politics",weight:3,title:"波茨坦会议与对日公告",summary:"三国重议德国处置，七月二十六日发表劝降公告。",detail:{background:"德国投降后，欧洲咨询委员会无法就德国的政府与边界取得一致，会议中途英国政府更替。",process:"7月17日至8月2日在波茨坦开会，确认德国非军事化、去纳粹化与四区管制，波兰西部边界留待对和约解决；26日中美英发表公告。",impact:"公告为日本设定接受条件，会议关于德国处置的四项原则构成1945至1949年占领立法的基础，也把德国的东部问题推给战后。",figures:["哈里·杜鲁门","温斯顿·丘吉尔","克莱门特·艾德礼","约瑟夫·斯大林"],place:"德国波茨坦",state:"美国／英国／苏联",sources:["1945年8月2日波茨坦会议议定书与公报正文","1945年7月26日中美英三国促令日本降伏之公告文本"],tags:["三巨头","德国处置","劝降公告"]},related:["world--1945--p01"]},
{id:"world--1945--m02",track:"world",year:1945,yearApprox:false,dim:"military",weight:4,title:"广岛与长崎的原子弹爆炸",summary:"八月六日与九日各投一枚，两城死难以十万至二十万计。",detail:{background:"1945年7月16日新墨西哥试验成功后，第509混合大队在提尼安岛装配可用的铀弹与钚弹。",process:"8月6日上午广岛遭铀弹爆炸，9日上午长崎遭钚弹爆炸，冲击波与热辐射随即引发大面积火灾与急性辐射病。",impact:"据两市战后调查与美国战略轰炸调查，至1945年底两城死亡分别约十四万与七万（属估算），幸存者与辐射后遗症问题延续数十年。",figures:["哈里·杜鲁门","莱斯利·格罗夫斯","保罗·蒂贝茨"],place:"日本广岛、长崎",state:"美国／日本",sources:["1945年9月美国战略轰炸调查团关于广岛与长崎损害的报告","广岛市与长崎市关于原爆死没者与被害的官方调查统计"],tags:["原子弹","平民伤亡","战争终结"]},related:["world--1942--s01"]},
{id:"world--1945--p05",track:"world",year:1945,yearApprox:false,dim:"politics",weight:3,title:"苏联对日宣战与满洲战役",summary:"八月九日红军越境，两周内击溃关东军主力。",detail:{background:"雅尔塔秘密协定规定在欧洲战事结束后两三个月对日作战，广岛爆炸两日后苏联对日宣战。",process:"8月9日起三个方面军自外贝加尔、滨海与北方方向进入中国东北，关东军被分合围，18日起奉命停止抵抗，9月2日签署投降文书。",impact:"日本在8月10日即召开御前会议考虑接受公告，南萨哈林与千岛群岛此后入苏联控制区，朝鲜半岛以北纬三十八度线分治。",figures:["亚历山大·华西列夫斯基","冈村宁次"],place:"中国东北、朝鲜半岛北部与南萨哈林",state:"苏联／日本",sources:["1945年8月8日苏联对日本宣战的照会与塔斯社公告","1945年8至9月苏联远东军总司令部作战通报"],tags:["对日作战","满洲战役","战后分界"]},related:["world--1945--m02", "cn--1945--p03"]},
{id:"world--1945--p06",track:"world",year:1945,yearApprox:false,dim:"politics",weight:5,title:"日本签署降伏文书与战争结束",summary:"八月十五日广播终战诏书，九月二日在密苏里号签字。",detail:{background:"8月9日苏联参战与长崎爆炸后，御前会议在保留国体与接受公告之间僵持，10日经由瑞士照会求释。",process:"8月15日以录音广播宣告接受《波茨坦公告》，9月2日重光葵与梅津美治郎在东京湾的密苏里号签署降伏文书，盟国占领随即开始。",impact:"占领期由盟国对日理事会与盟军总部共同管辖，1946至1948年的宪法、农地改革与东京审判均在此期间启动。",figures:["裕仁","重光葵","道格拉斯·麦克阿瑟"],place:"日本东京湾（密苏里号）",state:"日本／同盟国",sources:["1945年8月14日日本接受公告的照会与终战诏书文本","1945年9月2日《日本降伏文书》正文与各签署国文本"],tags:["降伏","盟国占领","战争终结"]},related:["world--1945--p05"]},
{id:"world--1945--i01",track:"world",year:1945,yearApprox:false,dim:"institution",weight:3,title:"纽伦堡审判开庭",summary:"四国军事法庭以三类罪行起诉主要战犯与六个组织。",detail:{background:"1943年12月莫斯科宣言已预告追究责任，1945年8月8日伦敦协定设立国际军事法庭并规定罪行类别。",process:"1945年11月20日首次开庭，起诉破坏和平罪、战争罪与反人类罪，二十余名被告与六个组织受审，1946年10月宣判。",impact:"审判确立国家官员个人刑责与服从命令不免责的原则，为1948年灭种罪公约与常设国际刑事法院的规约提供先例。",figures:["罗伯特·杰克逊","赫尔曼·戈林"],place:"德国纽伦堡（司法宫）",state:"美国／英国／苏联／法国",sources:["1945年8月8日《伦敦协定》与国际军事法庭章程正文","1945至1946年纽伦堡审判庭审记录与判决书（官方出版文本）"],tags:["国际刑法","反人类罪","战后清算"]},related:["world--1942--p01"]},
];

